export default [{"id":"0","title":"Hello!","words":[{"en":"April","vi":"tháng Tư","art":"1f327","ipa":"/ˈeɪ.prəl/","example":"My school exams will take place in the middle of April.","exampleVi":"Các kỳ thi ở trường của tôi sẽ diễn ra vào giữa tháng Tư.","audio":"vocab-audio/flyers/001.mp3"},{"en":"August","vi":"tháng Tám","art":"1f349","ipa":"/ˈɔː.ɡəst/","example":"Our family usually goes camping during the hot days of August.","exampleVi":"Gia đình chúng tôi thường đi cắm trại vào những ngày nóng nực của tháng Tám.","audio":"vocab-audio/flyers/002.mp3"},{"en":"aunt","vi":"cô, dì, bác gái","art":"1f9d5","ipa":"/ɑːnt/","example":"My aunt works as an English teacher at the university.","exampleVi":"Bác gái tôi làm giáo viên tiếng Anh tại trường đại học.","audio":"vocab-audio/flyers/003.mp3"},{"en":"brother","vi":"anh, em trai","art":"1f466","ipa":"/ˈbrʌð.ər/","example":"My elder brother is studying computer science at college.","exampleVi":"Anh trai tôi đang theo học ngành khoa học máy tính tại trường cao đẳng.","audio":"vocab-audio/flyers/004.mp3"},{"en":"cousin","vi":"anh chị em họ","art":"1f9d2","ipa":"/ˈkʌz.n/","example":"My cousin lives in London and sends me postcards regularly.","exampleVi":"Anh họ tôi sống ở Luân Đôn và thường xuyên gửi bưu thiếp cho tôi.","audio":"vocab-audio/flyers/005.mp3"},{"en":"dad","vi":"bố","art":"1f468","ipa":"/dæd/","example":"Dad has already repaired the broken engine of our car.","exampleVi":"Bố đã sửa xong động cơ bị hỏng của chiếc xe ô tô chúng tôi rồi.","audio":"vocab-audio/flyers/006.mp3"},{"en":"December","vi":"tháng Mười hai","art":"1f384","ipa":"/dɪˈsem.bər/","example":"We decorate a tall Christmas tree together every December.","exampleVi":"Chúng tôi cùng nhau trang trí một cây thông Noel cao vào mỗi tháng Mười hai.","audio":"vocab-audio/flyers/007.mp3"},{"en":"family tree","vi":"sơ đồ gia phả","art":"1f333","ipa":"/ˌfæm.əl.i ˈtriː/","example":"We drew our family tree with photographs of our great-grandparents.","exampleVi":"Chúng tôi đã vẽ sơ đồ gia phả với những bức ảnh của cụ cố.","audio":"vocab-audio/flyers/008.mp3"},{"en":"February","vi":"tháng Hai","art":"1f496","ipa":"/ˈfeb.ru.ər.i/","example":"February is the shortest month of the entire calendar year.","exampleVi":"Tháng Hai là tháng ngắn nhất trong cả năm dương lịch.","audio":"vocab-audio/flyers/009.mp3"},{"en":"grandma","vi":"bà","art":"1f475","ipa":"/ˈɡræn.mɑː/","example":"Grandma has baked some delicious biscuits for the weekend party.","exampleVi":"Bà đã nướng một vài chiếc bánh quy thơm ngon cho bữa tiệc cuối tuần.","audio":"vocab-audio/flyers/010.mp3"},{"en":"grandpa","vi":"ông","art":"1f474","ipa":"/ˈɡræn.pɑː/","example":"My grandpa taught me how to play chess when I was little.","exampleVi":"Ông đã dạy tôi cách chơi cờ vua khi tôi còn nhỏ.","audio":"vocab-audio/flyers/011.mp3"},{"en":"husband","vi":"chồng","art":"1f468","ipa":"/ˈhʌz.bənd/","example":"Her husband is an engineer who designs modern bridges.","exampleVi":"Chồng cô ấy là một kỹ sư chuyên thiết kế những cây cầu hiện đại.","audio":"vocab-audio/flyers/012.mp3"},{"en":"January","vi":"tháng Một","art":"2744","ipa":"/ˈdʒæn.ju.ər.i/","example":"January is often the coldest month of winter in many countries.","exampleVi":"Tháng Một thường là tháng lạnh nhất của mùa đông ở nhiều quốc gia.","audio":"vocab-audio/flyers/013.mp3"},{"en":"July","vi":"tháng Bảy","art":"1f3d6","ipa":"/dʒuˈlaɪ/","example":"We stayed at a seaside hotel throughout the sunny month of July.","exampleVi":"Chúng tôi đã ở một khách sạn ven biển trong suốt tháng Bảy ngập tràn ánh nắng.","audio":"vocab-audio/flyers/014.mp3"},{"en":"June","vi":"tháng Sáu","art":"2600","ipa":"/dʒuːn/","example":"Our summer vacation begins after the final exam in June.","exampleVi":"Kỳ nghỉ hè của chúng tôi bắt đầu sau kỳ thi cuối kỳ vào tháng Sáu.","audio":"vocab-audio/flyers/015.mp3"},{"en":"March","vi":"tháng Ba","art":"1f331","ipa":"/mɑːtʃ/","example":"Spring flowers begin to bloom beautifully in early March.","exampleVi":"Hoa mùa xuân bắt đầu nở rộ tuyệt đẹp vào đầu tháng Ba.","audio":"vocab-audio/flyers/016.mp3"},{"en":"May","vi":"tháng Năm","art":"1f338","ipa":"/meɪ/","example":"The weather in May is warm and pleasant for outdoor sports.","exampleVi":"Thời tiết vào tháng Năm thật ấm áp và dễ chịu cho các môn thể thao ngoài trời.","audio":"vocab-audio/flyers/017.mp3"},{"en":"month","vi":"tháng","art":"1f4c5","ipa":"/mʌnθ/","example":"Which month of the year do you like travelling in most?","exampleVi":"Bạn thích đi du lịch vào tháng nào nhất trong năm?","audio":"vocab-audio/flyers/018.mp3"},{"en":"mum","vi":"mẹ","art":"1f469","ipa":"/mʌm/","example":"Mum has prepared a wonderful picnic lunch for all of us.","exampleVi":"Mẹ đã chuẩn bị một bữa trưa dã ngoại tuyệt vời cho tất cả chúng tôi.","audio":"vocab-audio/flyers/019.mp3"},{"en":"November","vi":"tháng Mười một","art":"1f342","ipa":"/nəʊˈvem.bər/","example":"In November, autumn leaves fall rapidly before winter arrives.","exampleVi":"Vào tháng Mười một, lá mùa thu rụng nhanh trước khi mùa đông tới.","audio":"vocab-audio/flyers/020.mp3"},{"en":"October","vi":"tháng Mười","art":"1f383","ipa":"/ɒkˈtəʊ.bər/","example":"The school festival was celebrated at the end of October.","exampleVi":"Lễ hội của trường đã được tổ chức vào cuối tháng Mười.","audio":"vocab-audio/flyers/021.mp3"},{"en":"September","vi":"tháng Chín","art":"1f392","ipa":"/sepˈtem.bər/","example":"The new school year starts on the fifth of September.","exampleVi":"Năm học mới bắt đầu vào ngày mùng năm tháng Chín.","audio":"vocab-audio/flyers/022.mp3"},{"en":"sister","vi":"chị, em gái","art":"1f467","ipa":"/ˈsɪs.tər/","example":"My sister plays volleyball for the junior school team.","exampleVi":"Chị gái tôi chơi bóng chuyền cho đội tuyển của trường.","audio":"vocab-audio/flyers/023.mp3"},{"en":"surname","vi":"họ","art":"1f4db","ipa":"/ˈsɜː.neɪm/","example":"Please write your full name with your surname first.","exampleVi":"Làm ơn hãy viết đầy đủ họ tên của bạn với phần họ ở trước.","audio":"vocab-audio/flyers/024.mp3"},{"en":"thousand","vi":"một nghìn","art":"1f4b0","ipa":"/ˈθaʊ.zənd/","example":"More than a thousand people attended the concert in the stadium.","exampleVi":"Hơn một nghìn người đã tham dự buổi hòa nhạc trong sân vận động.","audio":"vocab-audio/flyers/025.mp3"},{"en":"twins","vi":"cặp song sinh","art":"1f46f","ipa":"/twɪnz/","example":"The twins look so similar that even teachers confuse them.","exampleVi":"Hai đứa trẻ sinh đôi trông giống nhau đến mức cả giáo viên cũng nhầm lẫn.","audio":"vocab-audio/flyers/026.mp3"},{"en":"uncle","vi":"chú, bác trai","art":"1f9d4","ipa":"/ˈʌŋ.kl/","example":"My uncle is a pilot who flies aeroplanes across the ocean.","exampleVi":"Chú tôi là một phi công lái máy bay bay qua đại dương.","audio":"vocab-audio/flyers/027.mp3"},{"en":"way","vi":"đường, cách","art":"1f6e4","ipa":"/weɪ/","example":"Could you please tell me the quickest way to the station?","exampleVi":"Bạn có thể chỉ cho tôi con đường nhanh nhất đến nhà ga được không?","audio":"vocab-audio/flyers/028.mp3"},{"en":"wife","vi":"vợ","art":"1f470","ipa":"/waɪf/","example":"The doctor and his wife travelled together across Europe.","exampleVi":"Vị bác sĩ và vợ ông ấy đã cùng nhau đi du lịch khắp châu Âu.","audio":"vocab-audio/flyers/029.mp3"}],"art":"1f44b"},{"id":"1","title":"Our home","words":[{"en":"after","vi":"sau","art":"23e9","ipa":"/ˈɑːf.tər/","example":"After finishing her homework, she helped her parents cook dinner.","exampleVi":"Sau khi hoàn thành bài tập về nhà, cô ấy đã giúp bố mẹ nấu bữa tối.","audio":"vocab-audio/flyers/030.mp3"},{"en":"anyone","vi":"bất kỳ ai","art":"1f9d1","ipa":"/ˈen.i.wʌn/","example":"Did anyone remember to turn off the lights before leaving?","exampleVi":"Đã có ai nhớ tắt đèn trước khi rời đi chưa?","audio":"vocab-audio/flyers/031.mp3"},{"en":"anything","vi":"bất kỳ thứ gì","art":"1f4e6","ipa":"/ˈen.i.θɪŋ/","example":"Is there anything interesting to watch on television tonight?","exampleVi":"Tối nay có chương trình gì thú vị để xem trên ti vi không?","audio":"vocab-audio/flyers/032.mp3"},{"en":"anywhere","vi":"bất kỳ đâu","art":"1f5fa","ipa":"/ˈen.i.weər/","example":"I couldn't find my dictionary anywhere in the classroom.","exampleVi":"Tôi không thể tìm thấy cuốn từ điển của mình ở bất kỳ đâu trong lớp học.","audio":"vocab-audio/flyers/033.mp3"},{"en":"arrive","vi":"đến nơi","art":"1f6ec","ipa":"/əˈraɪv/","example":"The flight from London will arrive at five in the afternoon.","exampleVi":"Chuyến bay từ Luân Đôn sẽ đến nơi vào lúc năm giờ chiều.","audio":"vocab-audio/flyers/034.mp3"},{"en":"away","vi":"đi xa","art":"1f6eb","ipa":"/əˈweɪ/","example":"Our grandparents live far away in a peaceful mountain village.","exampleVi":"Ông bà chúng tôi sống ở nơi xa xôi trong một ngôi làng trên núi thanh bình.","audio":"vocab-audio/flyers/035.mp3"},{"en":"before","vi":"trước","art":"23ea","ipa":"/bɪˈfɔːr/","example":"Make sure you check your bag before leaving for the airport.","exampleVi":"Hãy đảm bảo rằng bạn đã kiểm tra túi xách trước khi đi ra sân bay.","audio":"vocab-audio/flyers/036.mp3"},{"en":"bin","vi":"thùng rác","art":"1f5d1","ipa":"/bɪn/","example":"Please put empty plastic bottles into the recycling bin.","exampleVi":"Làm ơn hãy bỏ những chiếc chai nhựa rỗng vào thùng rác tái chế.","audio":"vocab-audio/flyers/037.mp3"},{"en":"bit","vi":"một chút","art":"1f90f","ipa":"/bɪt/","example":"The maths exercise was a bit difficult for the younger students.","exampleVi":"Bài tập toán hơi khó một chút đối với các bạn học sinh nhỏ tuổi.","audio":"vocab-audio/flyers/038.mp3"},{"en":"bored","vi":"buồn chán","art":"1f612","ipa":"/bɔːd/","example":"He felt bored because he had nothing exciting to do.","exampleVi":"Cậu ấy cảm thấy buồn chán vì chẳng có việc gì thú vị để làm.","audio":"vocab-audio/flyers/039.mp3"},{"en":"borrow","vi":"mượn","art":"1f91d","ipa":"/ˈbɒr.əʊ/","example":"Can I borrow your English dictionary for a few minutes?","exampleVi":"Tôi có thể mượn cuốn từ điển tiếng Anh của bạn vài phút được không?","audio":"vocab-audio/flyers/040.mp3"},{"en":"broken","vi":"bị hỏng","art":"1f494","ipa":"/ˈbrəʊ.kən/","example":"The mechanic repaired the broken wheel of the racing car.","exampleVi":"Người thợ máy đã sửa chiếc bánh xe bị hỏng của chiếc xe đua.","audio":"vocab-audio/flyers/041.mp3"},{"en":"brush","vi":"bàn chải, chải","art":"1faa5","ipa":"/brʌʃ/","example":"Always brush your teeth twice a day to protect them.","exampleVi":"Hãy luôn chải răng hai lần một ngày để bảo vệ hàm răng của bạn.","audio":"vocab-audio/flyers/042.mp3"},{"en":"channel","vi":"kênh truyền hình","art":"1f4fb","ipa":"/ˈtʃæn.əl/","example":"Which television channel shows programs about wild animals?","exampleVi":"Kênh truyền hình nào chiếu các chương trình về động vật hoang dã vậy?","audio":"vocab-audio/flyers/043.mp3"},{"en":"chat","vi":"trò chuyện","art":"1f4ac","ipa":"/tʃæt/","example":"My friends and I often chat online about school projects.","exampleVi":"Tôi và bạn bè thường trò chuyện trực tuyến về các dự án trường học.","audio":"vocab-audio/flyers/044.mp3"},{"en":"chess","vi":"cờ vua","art":"265f","ipa":"/tʃes/","example":"Playing chess requires great patience and clever thinking.","exampleVi":"Chơi cờ vua đòi hỏi sự kiên nhẫn cao và tư duy thông minh.","audio":"vocab-audio/flyers/045.mp3"},{"en":"college","vi":"trường cao đẳng","art":"1f393","ipa":"/ˈkɒl.ɪdʒ/","example":"She will study modern languages at college next year.","exampleVi":"Cô ấy sẽ học các ngôn ngữ hiện đại tại trường cao đẳng vào năm tới.","audio":"vocab-audio/flyers/046.mp3"},{"en":"comb","vi":"cái lược","art":"1f487","ipa":"/kəʊm/","example":"She used a wooden comb to smooth her long hair.","exampleVi":"Cô ấy dùng chiếc lược gỗ để chải mượt mái tóc dài của mình.","audio":"vocab-audio/flyers/047.mp3"},{"en":"cooker","vi":"bếp nấu","art":"1f373","ipa":"/ˈkʊk.ər/","example":"Be careful because the electric cooker is still very hot.","exampleVi":"Hãy cẩn thận vì chiếc bếp nấu điện vẫn còn rất nóng.","audio":"vocab-audio/flyers/048.mp3"},{"en":"cushion","vi":"gối tựa","art":"1f6cb","ipa":"/ˈkʊʃ.ən/","example":"There are soft, colourful cushions on the living room sofa.","exampleVi":"Có những chiếc gối tựa mềm mại đầy màu sắc trên ghế sofa phòng khách.","audio":"vocab-audio/flyers/049.mp3"},{"en":"cycle","vi":"đạp xe","art":"1f6b2","ipa":"/ˈsaɪ.kl/","example":"We cycle together along the quiet countryside path.","exampleVi":"Chúng tôi cùng nhau đạp xe dọc theo con đường làng quê yên ả.","audio":"vocab-audio/flyers/050.mp3"},{"en":"dear","vi":"thân mến","art":"1f48c","ipa":"/dɪər/","example":"Dear friend, thank you very much for your lovely postcard.","exampleVi":"Bạn thân mến, cảm ơn bạn rất nhiều vì tấm bưu thiếp đáng yêu.","audio":"vocab-audio/flyers/051.mp3"},{"en":"diary","vi":"nhật ký","art":"1f4d4","ipa":"/ˈdaɪə.ri/","example":"She writes about her daily experiences in her private diary.","exampleVi":"Cô ấy viết về những trải nghiệm hàng ngày vào cuốn nhật ký riêng của mình.","audio":"vocab-audio/flyers/052.mp3"},{"en":"drums","vi":"trống","art":"1f941","ipa":"/drʌmz/","example":"He practises playing the drums in the music room every day.","exampleVi":"Cậu ấy luyện đánh trống trong phòng âm nhạc mỗi ngày.","audio":"vocab-audio/flyers/053.mp3"},{"en":"empty","vi":"trống rỗng","art":"1f5d1","ipa":"/ˈemp.ti/","example":"The theatre was completely empty after the musical ended.","exampleVi":"Nhà hát hoàn toàn trống rỗng sau khi vở nhạc kịch kết thúc.","audio":"vocab-audio/flyers/054.mp3"},{"en":"envelope","vi":"phong bì","art":"2709","ipa":"/ˈen.və.ləʊp/","example":"Put the invitation inside the white envelope carefully.","exampleVi":"Hãy đặt lá thư mời vào bên trong phong bì trắng một cách cẩn thận.","audio":"vocab-audio/flyers/055.mp3"},{"en":"everyone","vi":"mọi người","art":"1f465","ipa":"/ˈev.ri.wʌn/","example":"Everyone was amazed by the magician's wonderful performance.","exampleVi":"Mọi người đều kinh ngạc trước màn trình diễn tuyệt vời của nhà ảo thuật.","audio":"vocab-audio/flyers/056.mp3"},{"en":"everything","vi":"mọi thứ","art":"1f30e","ipa":"/ˈev.ri.θɪŋ/","example":"We made sure everything was ready for the camping adventure.","exampleVi":"Chúng tôi đảm bảo mọi thứ đã sẵn sàng cho chuyến phiêu lưu cắm trại.","audio":"vocab-audio/flyers/057.mp3"},{"en":"everywhere","vi":"khắp nơi","art":"1f30d","ipa":"/ˈev.ri.weər/","example":"We searched everywhere in the house for the missing key.","exampleVi":"Chúng tôi đã tìm kiếm khắp nơi trong nhà để tìm chiếc chìa khóa bị mất.","audio":"vocab-audio/flyers/058.mp3"},{"en":"file","vi":"tệp hồ sơ","art":"1f4c1","ipa":"/faɪl/","example":"Save the computer file before you turn off the screen.","exampleVi":"Hãy lưu tệp hồ sơ máy tính lại trước khi bạn tắt màn hình.","audio":"vocab-audio/flyers/059.mp3"},{"en":"fridge","vi":"tủ lạnh","art":"1f9ca","ipa":"/frɪdʒ/","example":"Keep the milk and cheese cold inside the fridge.","exampleVi":"Hãy bảo quản sữa và phô mai lạnh ở bên trong tủ lạnh.","audio":"vocab-audio/flyers/060.mp3"},{"en":"friendly","vi":"thân thiện","art":"1f60a","ipa":"/ˈfrend.li/","example":"The local people in the village were extremely friendly.","exampleVi":"Người dân địa phương trong làng cực kỳ thân thiện.","audio":"vocab-audio/flyers/061.mp3"},{"en":"full","vi":"đầy","art":"1f315","ipa":"/fʊl/","example":"The stadium was full of excited supporters before the match.","exampleVi":"Sân vận động đã chật kín những cổ động viên hào hứng trước trận đấu.","audio":"vocab-audio/flyers/062.mp3"},{"en":"fun","vi":"vui","art":"1f388","ipa":"/fʌn/","example":"Joining the school sports club was great fun for all of us.","exampleVi":"Tham gia câu lạc bộ thể thao của trường là niềm vui lớn cho tất cả chúng tôi.","audio":"vocab-audio/flyers/063.mp3"},{"en":"go out","vi":"đi ra ngoài","art":"1f6aa","ipa":"/ɡəʊ aʊt/","example":"We couldn't go out because the storm was too dangerous.","exampleVi":"Chúng tôi không thể đi ra ngoài vì cơn bão quá nguy hiểm.","audio":"vocab-audio/flyers/064.mp3"},{"en":"important","vi":"quan trọng","art":"2b50","ipa":"/ɪmˈpɔː.tənt/","example":"Learning a foreign language is very important for the future.","exampleVi":"Học một ngoại ngữ là điều rất quan trọng cho tương lai.","audio":"vocab-audio/flyers/065.mp3"},{"en":"interesting","vi":"thú vị","art":"1f9d0","ipa":"/ˈɪn.trəs.tɪŋ/","example":"The geography lesson about distant planets was very interesting.","exampleVi":"Bài học địa lý về các hành tinh xa xôi rất thú vị.","audio":"vocab-audio/flyers/066.mp3"},{"en":"keep","vi":"giữ","art":"1f512","ipa":"/kiːp/","example":"You must keep your passport and money in a safe pocket.","exampleVi":"Bạn phải giữ hộ chiếu và tiền trong một chiếc túi an toàn.","audio":"vocab-audio/flyers/067.mp3"},{"en":"key","vi":"chìa khóa","art":"1f511","ipa":"/kiː/","example":"Don't forget to take the front door key before leaving.","exampleVi":"Đừng quên mang chìa khóa cửa trước trước khi rời đi nhé.","audio":"vocab-audio/flyers/068.mp3"},{"en":"kind","vi":"tử tế","art":"1f917","ipa":"/kaɪnd/","example":"The teacher was kind and helped me correct my mistakes.","exampleVi":"Cô giáo rất tử tế và đã giúp tôi sửa những lỗi sai của mình.","audio":"vocab-audio/flyers/069.mp3"},{"en":"late","vi":"muộn","art":"23f3","ipa":"/leɪt/","example":"He ran as fast as he could so he wouldn't be late.","exampleVi":"Cậu ấy chạy nhanh nhất có thể để không bị muộn.","audio":"vocab-audio/flyers/070.mp3"},{"en":"letter","vi":"bức thư","art":"1f4e8","ipa":"/ˈlet.ər/","example":"I received an exciting letter from my penfriend in London.","exampleVi":"Tôi đã nhận được một bức thư hào hứng từ người bạn qua thư ở Luân Đôn.","audio":"vocab-audio/flyers/071.mp3"},{"en":"little","vi":"nhỏ","art":"1f423","ipa":"/ˈlɪt.l/","example":"There was a little bird building a nest on the branch.","exampleVi":"Có một chú chim nhỏ đang làm tổ trên cành cây.","audio":"vocab-audio/flyers/072.mp3"},{"en":"lucky","vi":"may mắn","art":"1f340","ipa":"/ˈlʌk.i/","example":"We were lucky that the rain stopped before the competition began.","exampleVi":"Chúng tôi thật may mắn khi cơn mưa tạnh trước khi cuộc thi bắt đầu.","audio":"vocab-audio/flyers/073.mp3"},{"en":"meal","vi":"bữa ăn","art":"1f37d","ipa":"/mɪəl/","example":"Breakfast is considered the most important meal of the day.","exampleVi":"Bữa sáng được xem là bữa ăn quan trọng nhất trong ngày.","audio":"vocab-audio/flyers/074.mp3"},{"en":"much","vi":"nhiều (không đếm được)","art":"1f4b0","ipa":"/mʌtʃ/","example":"How much time do we have left before the train leaves?","exampleVi":"Chúng ta còn lại bao nhiêu thời gian trước khi tàu rời ga?","audio":"vocab-audio/flyers/075.mp3"},{"en":"necklace","vi":"vòng cổ","art":"1f4ff","ipa":"/ˈnek.ləs/","example":"My mother wore a beautiful silver necklace to the dinner.","exampleVi":"Mẹ tôi đã đeo một chiếc vòng cổ bằng bạc tuyệt đẹp tới bữa tối.","audio":"vocab-audio/flyers/076.mp3"},{"en":"news","vi":"tin tức","art":"1f4f0","ipa":"/njuːz/","example":"The radio news reported that the motorway was blocked.","exampleVi":"Tin tức trên đài phát thanh đưa tin rằng đường cao tốc đã bị tắc nghẽn.","audio":"vocab-audio/flyers/077.mp3"},{"en":"noisy","vi":"ồn ào","art":"1f50a","ipa":"/ˈnɔɪ.zi/","example":"The town centre was too noisy because of heavy traffic.","exampleVi":"Trung tâm thị trấn quá ồn ào vì lượng giao thông đông đúc.","audio":"vocab-audio/flyers/078.mp3"},{"en":"no-one","vi":"không ai","art":"1f6ab","ipa":"/ˈnəʊ.wʌn/","example":"No-one in our class knew the answer to that difficult question.","exampleVi":"Không ai trong lớp chúng tôi biết câu trả lời cho câu hỏi khó đó.","audio":"vocab-audio/flyers/079.mp3"},{"en":"of course","vi":"tất nhiên","art":"1f44d","ipa":"/əv kɔːs/","example":"Of course you can borrow my dictionary whenever you need it.","exampleVi":"Tất nhiên là bạn có thể mượn từ điển của tôi bất cứ khi nào bạn cần.","audio":"vocab-audio/flyers/080.mp3"},{"en":"oven","vi":"lò nướng","art":"1f372","ipa":"/ˈʌv.ən/","example":"Mum baked delicious fruit pies in the electric oven.","exampleVi":"Mẹ đã nướng những chiếc bánh nướng trái cây thơm ngon trong lò nướng điện.","audio":"vocab-audio/flyers/081.mp3"},{"en":"paper","vi":"giấy","art":"1f4c4","ipa":"/ˈpeɪ.pər/","example":"Write your answers clearly on this sheet of paper.","exampleVi":"Hãy viết câu trả lời của bạn một cách rõ ràng trên tờ giấy này.","audio":"vocab-audio/flyers/082.mp3"},{"en":"popular","vi":"được yêu thích","art":"1f525","ipa":"/ˈpɒp.jə.lər/","example":"Football is the most popular sport among young students.","exampleVi":"Bóng đá là môn thể thao được yêu thích nhất trong giới học sinh trẻ.","audio":"vocab-audio/flyers/083.mp3"},{"en":"post","vi":"gửi bưu điện","art":"1f4eb","ipa":"/pəʊst/","example":"I will post this birthday card to my grandma tomorrow.","exampleVi":"Tôi sẽ gửi bưu điện tấm thiệp sinh nhật này cho bà vào ngày mai.","audio":"vocab-audio/flyers/084.mp3"},{"en":"postcard","vi":"bưu thiếp","art":"1f4ee","ipa":"/ˈpəʊst.kɑːd/","example":"We bought a lovely postcard showing the ancient castle.","exampleVi":"Chúng tôi đã mua một tấm bưu thiếp xinh xắn in hình lâu đài cổ kính.","audio":"vocab-audio/flyers/085.mp3"},{"en":"programme","vi":"chương trình","art":"1f4fa","ipa":"/ˈprəʊ.ɡræm/","example":"We watched an exciting science programme on television last night.","exampleVi":"Tối qua chúng tôi đã xem một chương trình khoa học hào hứng trên ti vi.","audio":"vocab-audio/flyers/086.mp3"},{"en":"quiet","vi":"yên tĩnh","art":"1f926","ipa":"/ˈkwaɪ.ət/","example":"The reading room in the library was peaceful and quiet.","exampleVi":"Phòng đọc trong thư viện thật thanh bình và yên tĩnh.","audio":"vocab-audio/flyers/087.mp3"},{"en":"rucksack","vi":"ba lô","art":"1f392","ipa":"/ˈrʌk.sæk/","example":"Pack your raincoat and water bottle inside your rucksack.","exampleVi":"Hãy cất áo mưa và chai nước vào trong chiếc ba lô của bạn.","audio":"vocab-audio/flyers/088.mp3"},{"en":"search","vi":"tìm kiếm","art":"1f50d","ipa":"/sɜːtʃ/","example":"Scientists search for new species in deep oceans.","exampleVi":"Các nhà khoa học tìm kiếm những loài sinh vật mới ở các đại dương sâu thẳm.","audio":"vocab-audio/flyers/089.mp3"},{"en":"shampoo","vi":"dầu gội","art":"1f9f4","ipa":"/ʃæmˈpuː/","example":"Use this gentle shampoo to wash your hair.","exampleVi":"Hãy dùng loại dầu gội dịu nhẹ này để gội đầu.","audio":"vocab-audio/flyers/090.mp3"},{"en":"shelf","vi":"kệ","art":"1f4da","ipa":"/ʃelf/","example":"There are dozens of thick dictionaries on the top shelf.","exampleVi":"Có hàng tá cuốn từ điển dày trên chiếc kệ trên cùng.","audio":"vocab-audio/flyers/091.mp3"},{"en":"soap","vi":"xà phòng","art":"1f9fc","ipa":"/səʊp/","example":"Wash your hands thoroughly with soap and warm water.","exampleVi":"Hãy rửa tay kỹ bằng xà phòng và nước ấm.","audio":"vocab-audio/flyers/092.mp3"},{"en":"somewhere","vi":"ở đâu đó","art":"1f5fa","ipa":"/ˈsʌm.weər/","example":"I left my glasses somewhere in the living room.","exampleVi":"Tôi đã để quên kính mắt ở đâu đó trong phòng khách.","audio":"vocab-audio/flyers/093.mp3"},{"en":"stamps","vi":"tem thư","art":"1f4ec","ipa":"/stæmps/","example":"He collects colourful stamps from countries all over the world.","exampleVi":"Cậu ấy sưu tầm những con tem thư sặc sỡ từ các quốc gia trên khắp thế giới.","audio":"vocab-audio/flyers/094.mp3"},{"en":"take","vi":"lấy, mang","art":"270b","ipa":"/teɪk/","example":"It takes about forty minutes to get to the museum by bus.","exampleVi":"Mất khoảng bốn mươi phút để đi đến bảo tàng bằng xe buýt.","audio":"vocab-audio/flyers/095.mp3"},{"en":"teach","vi":"dạy","art":"1f469-200d-1f3eb","ipa":"/tiːtʃ/","example":"Our science teacher will teach us about the planets tomorrow.","exampleVi":"Giáo viên khoa học của chúng tôi sẽ dạy chúng tôi về các hành tinh vào ngày mai.","audio":"vocab-audio/flyers/096.mp3"},{"en":"tidy","vi":"gọn gàng","art":"2728","ipa":"/ˈtaɪ.di/","example":"Make sure your bedroom is neat and tidy before leaving.","exampleVi":"Hãy đảm bảo phòng ngủ của bạn ngăn nắp và gọn gàng trước khi rời đi.","audio":"vocab-audio/flyers/097.mp3"},{"en":"time","vi":"thời gian","art":"23f0","ipa":"/taɪm/","example":"What time does the evening train leave the station?","exampleVi":"Chuyến tàu buổi tối rời nhà ga vào thời gian mấy giờ?","audio":"vocab-audio/flyers/098.mp3"},{"en":"toothpaste","vi":"kem đánh răng","art":"1faa5","ipa":"/ˈtuːθ.peɪst/","example":"Dentists recommend using toothpaste with fluoride every day.","exampleVi":"Các nha sĩ khuyên dùng kem đánh răng chứa florua mỗi ngày.","audio":"vocab-audio/flyers/099.mp3"},{"en":"unfriendly","vi":"không thân thiện","art":"1f620","ipa":"/ʌnˈfrend.li/","example":"The dog barked in an unfriendly way at strangers.","exampleVi":"Con chó đã sủa một cách không thân thiện về phía những người lạ.","audio":"vocab-audio/flyers/100.mp3"},{"en":"unhappy","vi":"không vui","art":"1f641","ipa":"/ʌnˈhæp.i/","example":"She looked unhappy because she couldn't find her favourite toy.","exampleVi":"Cô bé trông không vui vì không thể tìm thấy món đồ chơi yêu thích.","audio":"vocab-audio/flyers/101.mp3"},{"en":"unkind","vi":"không tử tế","art":"1f47f","ipa":"/ʌnˈkaɪnd/","example":"It is unkind to laugh at other people's mistakes.","exampleVi":"Thật không tử tế khi cười nhạo lỗi sai của người khác.","audio":"vocab-audio/flyers/102.mp3"},{"en":"untidy","vi":"bừa bộn","art":"1f9fa","ipa":"/ʌnˈtaɪ.di/","example":"His room was untidy with comic books scattered all over the floor.","exampleVi":"Phòng của cậu ấy rất bừa bộn với những cuốn truyện tranh vương vãi khắp sàn.","audio":"vocab-audio/flyers/103.mp3"},{"en":"usually","vi":"thường thường","art":"1f4c5","ipa":"/ˈjuː.ʒu.ə.li/","example":"I usually finish my homework before having dinner with my family.","exampleVi":"Tôi thường thường hoàn thành bài tập về nhà trước khi ăn tối cùng gia đình.","audio":"vocab-audio/flyers/104.mp3"},{"en":"violin","vi":"đàn vi-ô-lông","art":"1f3bb","ipa":"/ˌvaɪəˈlɪn/","example":"She has been learning to play the violin for three years.","exampleVi":"Cô ấy đã học chơi đàn vi-ô-lông được ba năm rồi.","audio":"vocab-audio/flyers/105.mp3"},{"en":"warm","vi":"ấm","art":"2600","ipa":"/wɔːm/","example":"Put on a warm woollen sweater because it is windy outside.","exampleVi":"Hãy mặc một chiếc áo len ấm áp vì bên ngoài trời đang có gió.","audio":"vocab-audio/flyers/106.mp3"},{"en":"wheel","vi":"bánh xe","art":"1f6de","ipa":"/wiːl/","example":"The mechanic replaced the front wheel of the bicycle.","exampleVi":"Người thợ máy đã thay chiếc bánh xe phía trước của chiếc xe đạp.","audio":"vocab-audio/flyers/107.mp3"},{"en":"wifi","vi":"mạng không dây","art":"1f4f6","ipa":"/ˈwaɪ.faɪ/","example":"Can you tell me the password for the hotel wifi?","exampleVi":"Bạn có thể cho tôi biết mật khẩu mạng không dây của khách sạn không?","audio":"vocab-audio/flyers/108.mp3"}],"art":"1f3e1"},{"id":"2","title":"Going to town","words":[{"en":"across","vi":"băng qua","art":"27a1","ipa":"/əˈkrɒs/","example":"They walked carefully across the ancient stone bridge.","exampleVi":"Họ đã cẩn thận đi bộ băng qua cây cầu đá cổ kính.","audio":"vocab-audio/flyers/109.mp3"},{"en":"airport","vi":"sân bay","art":"1f6eb","ipa":"/ˈeə.pɔːt/","example":"We arrived at the international airport two hours before our flight.","exampleVi":"Chúng tôi đã đến sân bay quốc tế hai tiếng trước giờ bay.","audio":"vocab-audio/flyers/110.mp3"},{"en":"ambulance","vi":"xe cứu thương","art":"1f691","ipa":"/ˈæm.bjə.ləns/","example":"The ambulance arrived quickly to help the injured driver.","exampleVi":"Xe cứu thương đã đến nhanh chóng để giúp đỡ người tài xế bị thương.","audio":"vocab-audio/flyers/111.mp3"},{"en":"bank","vi":"ngân hàng","art":"1f3e6","ipa":"/bæŋk/","example":"Mum went to the bank in town to withdraw some money.","exampleVi":"Mẹ đã đến ngân hàng trong thị trấn để rút một ít tiền.","audio":"vocab-audio/flyers/112.mp3"},{"en":"bicycle","vi":"xe đạp","art":"1f6b2","ipa":"/ˈbaɪ.sɪ.kl/","example":"Riding a bicycle is an excellent way to keep fit.","exampleVi":"Đi xe đạp là một cách tuyệt vời để giữ gìn sức khỏe.","audio":"vocab-audio/flyers/113.mp3"},{"en":"bridge","vi":"cây cầu","art":"1f309","ipa":"/brɪdʒ/","example":"The long suspension bridge crosses the wide blue river.","exampleVi":"Cây cầu treo dài bắc ngang qua dòng sông xanh rộng lớn.","audio":"vocab-audio/flyers/114.mp3"},{"en":"castle","vi":"lâu đài","art":"1f3f0","ipa":"/ˈkɑː.sl/","example":"The ancient castle on the hill was built hundreds of years ago.","exampleVi":"Tòa lâu đài cổ kính trên đồi được xây dựng từ hàng trăm năm trước.","audio":"vocab-audio/flyers/115.mp3"},{"en":"chemist’s","vi":"hiệu thuốc","art":"1f48a","ipa":"/ˈkem.ɪsts/","example":"Dad bought some cough medicine at the chemist’s near the station.","exampleVi":"Bố đã mua một ít thuốc ho tại hiệu thuốc gần nhà ga.","audio":"vocab-audio/flyers/116.mp3"},{"en":"corner","vi":"góc","art":"21a9","ipa":"/ˈkɔː.nər/","example":"There is a lovely flower shop on the corner of the street.","exampleVi":"Có một cửa hàng hoa đáng yêu ở góc phố.","audio":"vocab-audio/flyers/117.mp3"},{"en":"expensive","vi":"đắt tiền","art":"1f4b0","ipa":"/ɪkˈspen.sɪv/","example":"That new racing bicycle was too expensive for him to buy.","exampleVi":"Chiếc xe đạp đua mới đó quá đắt tiền để cậu ấy có thể mua.","audio":"vocab-audio/flyers/118.mp3"},{"en":"factory","vi":"nhà máy","art":"1f3ed","ipa":"/ˈfæk.tər.i/","example":"My uncle works as an engineer in a car factory.","exampleVi":"Chú tôi làm kỹ sư trong một nhà máy sản xuất ô tô.","audio":"vocab-audio/flyers/119.mp3"},{"en":"fetch","vi":"đi lấy","art":"1f415","ipa":"/fetʃ/","example":"The dog ran across the garden to fetch the yellow ball.","exampleVi":"Con chó đã chạy qua vườn để đi lấy quả bóng màu vàng.","audio":"vocab-audio/flyers/120.mp3"},{"en":"fire engine","vi":"xe cứu hỏa","art":"1f692","ipa":"/ˈfaɪə ˌen.dʒɪn/","example":"The red fire engine rushed down the street with loud sirens.","exampleVi":"Chiếc xe cứu hỏa màu đỏ lao nhanh xuống phố với tiếng còi hú vang.","audio":"vocab-audio/flyers/121.mp3"},{"en":"fire station","vi":"trạm cứu hỏa","art":"1f692","ipa":"/ˈfaɪə ˌsteɪ.ʃən/","example":"We visited the local fire station during our school trip.","exampleVi":"Chúng tôi đã đến thăm trạm cứu hỏa địa phương trong chuyến dã ngoại của trường.","audio":"vocab-audio/flyers/122.mp3"},{"en":"forget","vi":"quên","art":"1f937","ipa":"/fəˈɡet/","example":"Don't forget to take your umbrella when you leave the house.","exampleVi":"Đừng quên mang ô theo khi bạn ra khỏi nhà nhé.","audio":"vocab-audio/flyers/123.mp3"},{"en":"front","vi":"phía trước","art":"1f449","ipa":"/frʌnt/","example":"The headteacher stood at the front of the classroom to speak.","exampleVi":"Thầy hiệu trưởng đã đứng ở phía trước lớp học để phát biểu.","audio":"vocab-audio/flyers/124.mp3"},{"en":"get to","vi":"đến","art":"1f3c3","ipa":"/ɡet tuː/","example":"How long does it take to get to the airport by taxi?","exampleVi":"Mất bao lâu để đến sân bay bằng xe taxi?","audio":"vocab-audio/flyers/125.mp3"},{"en":"hill","vi":"đồi","art":"26f0","ipa":"/hɪl/","example":"They walked up the steep hill to see the sunset.","exampleVi":"Họ đã đi bộ lên ngọn đồi dốc để ngắm hoàng hôn.","audio":"vocab-audio/flyers/126.mp3"},{"en":"hotel","vi":"khách sạn","art":"1f3e8","ipa":"/həʊˈtel/","example":"Our family stayed at a luxurious hotel near the beach.","exampleVi":"Gia đình chúng tôi đã ở một khách sạn sang trọng gần bãi biển.","audio":"vocab-audio/flyers/127.mp3"},{"en":"How long?","vi":"Bao lâu?","art":"23f3","ipa":"/haʊ lɒŋ/","example":"How long have you lived in this historic town?","exampleVi":"Bạn đã sống ở thị trấn lịch sử này được bao lâu rồi?","audio":"vocab-audio/flyers/128.mp3"},{"en":"later","vi":"sau đó","art":"23f0","ipa":"/ˈleɪ.tər/","example":"I will finish this difficult exercise later this evening.","exampleVi":"Tôi sẽ hoàn thành bài tập khó này sau vào tối nay.","audio":"vocab-audio/flyers/129.mp3"},{"en":"left","vi":"bên trái","art":"2b05","ipa":"/left/","example":"Turn left at the traffic lights to reach the post office.","exampleVi":"Hãy rẽ bên trái tại cột đèn giao thông để đến bưu điện.","audio":"vocab-audio/flyers/130.mp3"},{"en":"middle","vi":"ở giữa","art":"1f3af","ipa":"/ˈmɪd.l/","example":"A fountain stands right in the middle of the town square.","exampleVi":"Một đài phun nước đứng ngay ở giữa quảng trường thị trấn.","audio":"vocab-audio/flyers/131.mp3"},{"en":"money","vi":"tiền","art":"1f4b5","ipa":"/ˈmʌn.i/","example":"She saved her pocket money to buy a new book.","exampleVi":"Cô ấy đã tiết kiệm tiền tiêu vặt để mua một cuốn sách mới.","audio":"vocab-audio/flyers/132.mp3"},{"en":"motorway","vi":"đường cao tốc","art":"1f6e3","ipa":"/ˈməʊ.tə.weɪ/","example":"Traffic was moving fast along the busy motorway.","exampleVi":"Giao thông đang di chuyển rất nhanh dọc theo đường cao tốc đông đúc.","audio":"vocab-audio/flyers/133.mp3"},{"en":"museum","vi":"bảo tàng","art":"1f3db","ipa":"/mjuːˈziː.əm/","example":"We learned a lot about dinosaurs at the science museum.","exampleVi":"Chúng tôi đã học được rất nhiều về khủng long tại bảo tàng khoa học.","audio":"vocab-audio/flyers/134.mp3"},{"en":"next","vi":"tiếp theo","art":"23ed","ipa":"/nekst/","example":"Who is the next player to serve the tennis ball?","exampleVi":"Ai là người chơi tiếp theo thực hiện quả giao bóng tennis?","audio":"vocab-audio/flyers/135.mp3"},{"en":"other","vi":"khác","art":"1f500","ipa":"/ˈʌð.ər/","example":"Some students like football while other students prefer tennis.","exampleVi":"Một số học sinh thích bóng đá trong khi các học sinh khác lại chuộng quần vợt.","audio":"vocab-audio/flyers/136.mp3"},{"en":"over","vi":"qua bên trên","art":"2934","ipa":"/ˈəʊ.vər/","example":"The aeroplane flew directly over the snow-covered mountains.","exampleVi":"Chiếc máy bay đã bay qua bên trên những ngọn núi phủ đầy tuyết.","audio":"vocab-audio/flyers/137.mp3"},{"en":"past","vi":"đi ngang qua","art":"1f995","ipa":"/pɑːst/","example":"We walked past the old post office on our way to school.","exampleVi":"Chúng tôi đã đi ngang qua bưu điện cũ trên đường đến trường.","audio":"vocab-audio/flyers/138.mp3"},{"en":"police station","vi":"đồn cảnh sát","art":"1f3e2","ipa":"/pəˈliːs ˌsteɪ.ʃən/","example":"He went to the police station to report his lost wallet.","exampleVi":"Anh ấy đã đến đồn cảnh sát để báo việc bị mất ví.","audio":"vocab-audio/flyers/139.mp3"},{"en":"post office","vi":"bưu điện","art":"1f4ee","ipa":"/ˈpəʊst ˌɒf.ɪs/","example":"You can buy stamps and send parcels at the post office.","exampleVi":"Bạn có thể mua tem và gửi bưu kiện tại bưu điện.","audio":"vocab-audio/flyers/140.mp3"},{"en":"pyjamas","vi":"đồ ngủ","art":"1f97c","ipa":"/pɪˈdʒɑː.məz/","example":"I changed into my warm pyjamas before going to sleep.","exampleVi":"Tôi đã thay bộ đồ ngủ ấm áp trước khi đi ngủ.","audio":"vocab-audio/flyers/141.mp3"},{"en":"railway station","vi":"ga tàu hỏa","art":"1f689","ipa":"/ˈreɪl.weɪ ˌsteɪ.ʃən/","example":"Thousands of passengers arrive at the railway station every day.","exampleVi":"Hàng nghìn hành khách đến ga tàu hỏa mỗi ngày.","audio":"vocab-audio/flyers/142.mp3"},{"en":"remember","vi":"nhớ","art":"1f9e0","ipa":"/rɪˈmem.bər/","example":"Please remember to bring your sports trainers tomorrow.","exampleVi":"Làm ơn hãy nhớ mang giày thể thao của bạn vào ngày mai.","audio":"vocab-audio/flyers/143.mp3"},{"en":"restaurant","vi":"nhà hàng","art":"1f37d","ipa":"/ˈres.trɒnt/","example":"We celebrated my sister's birthday at an Italian restaurant.","exampleVi":"Chúng tôi đã tổ chức sinh nhật cho chị gái tại một nhà hàng Ý.","audio":"vocab-audio/flyers/144.mp3"},{"en":"right","vi":"bên phải","ipa":"/raɪt/","example":"Turn right after crossing the bridge to find the museum.","exampleVi":"Hãy rẽ bên phải sau khi qua cầu để tìm thấy bảo tàng.","audio":"vocab-audio/flyers/145.mp3"},{"en":"shorts","vi":"quần đùi","art":"1fa73","ipa":"/ʃɔːts/","example":"He wore comfortable blue shorts to the beach.","exampleVi":"Cậu ấy mặc chiếc quần đùi màu xanh thoải mái ra bãi biển.","audio":"vocab-audio/flyers/146.mp3"},{"en":"sky","vi":"bầu trời","art":"2601","ipa":"/skaɪ/","example":"The dark evening sky was filled with bright twinkling stars.","exampleVi":"Bầu trời đêm tối tràn ngập những ngôi sao lấp lánh sáng rực.","audio":"vocab-audio/flyers/147.mp3"},{"en":"skyscraper","vi":"tòa nhà chọc trời","art":"1f3d9","ipa":"/ˈskaɪˌskreɪ.pər/","example":"The glass skyscraper was the tallest building in the city.","exampleVi":"Tòa nhà chọc trời bằng kính là công trình cao nhất trong thành phố.","audio":"vocab-audio/flyers/148.mp3"},{"en":"stadium","vi":"sân vận động","art":"1f3df","ipa":"/ˈsteɪ.di.əm/","example":"The football match will take place at the national stadium.","exampleVi":"Trận bóng đá sẽ diễn ra tại sân vận động quốc gia.","audio":"vocab-audio/flyers/149.mp3"},{"en":"taxi","vi":"xe taxi","art":"1f695","ipa":"/ˈtæk.si/","example":"We took a yellow taxi to the railway station.","exampleVi":"Chúng tôi đã bắt một chiếc xe taxi màu vàng để đến ga tàu.","audio":"vocab-audio/flyers/150.mp3"},{"en":"through","vi":"xuyên qua","art":"27a1","ipa":"/θruː/","example":"The train passed smoothly through a long mountain tunnel.","exampleVi":"Đoàn tàu lướt êm ái xuyên qua một đường hầm dài xuyên núi.","audio":"vocab-audio/flyers/151.mp3"},{"en":"traffic","vi":"giao thông","art":"1f6a5","ipa":"/ˈtræf.ɪk/","example":"There was a lot of traffic on the roads this morning.","exampleVi":"Có rất nhiều phương tiện giao thông trên đường vào sáng nay.","audio":"vocab-audio/flyers/152.mp3"},{"en":"university","vi":"trường đại học","art":"1f3eb","ipa":"/ˌjuː.nɪˈvɜː.sə.ti/","example":"She wants to study medicine at university to become a doctor.","exampleVi":"Cô ấy muốn học ngành y tại trường đại học để trở thành bác sĩ.","audio":"vocab-audio/flyers/153.mp3"},{"en":"will","vi":"sẽ","art":"1f52e","ipa":"/wɪl/","example":"The weather forecast says it will rain heavily tomorrow.","exampleVi":"Dự báo thời tiết nói rằng ngày mai trời sẽ mưa to.","audio":"vocab-audio/flyers/154.mp3"},{"en":"wood","vi":"gỗ","art":"1fab5","ipa":"/wʊd/","example":"This antique dining table is made of solid wood.","exampleVi":"Chiếc bàn ăn cổ này được làm bằng gỗ nguyên khối.","audio":"vocab-audio/flyers/155.mp3"}],"art":"1f3d9"},{"id":"3","title":"Eating out","words":[{"en":"amazing","vi":"đáng kinh ngạc","art":"2728","ipa":"/əˈmeɪ.zɪŋ/","example":"The view from the top of the mountain was truly amazing.","exampleVi":"Quang cảnh từ trên đỉnh núi thật đáng kinh ngạc.","audio":"vocab-audio/flyers/156.mp3"},{"en":"biscuit","vi":"bánh quy","art":"1f36a","ipa":"/ˈbɪs.kɪt/","example":"Would you like a chocolate biscuit with your hot milk?","exampleVi":"Bạn có muốn ăn một chiếc bánh quy sô-cô-la cùng sữa nóng không?","audio":"vocab-audio/flyers/157.mp3"},{"en":"bracelet","vi":"vòng tay","art":"1f4ff","ipa":"/ˈbreɪ.slət/","example":"Grandma gave me a delicate silver bracelet for my birthday.","exampleVi":"Bà đã tặng tôi một chiếc vòng tay bằng bạc tinh xảo nhân dịp sinh nhật.","audio":"vocab-audio/flyers/158.mp3"},{"en":"butter","vi":"bơ","art":"1f9c8","ipa":"/ˈbʌt.ər/","example":"Spread a little butter on the warm slice of bread.","exampleVi":"Hãy quết một ít bơ lên lát bánh mì ấm.","audio":"vocab-audio/flyers/159.mp3"},{"en":"chopsticks","vi":"đũa","art":"1f962","ipa":"/ˈtʃɒp.stɪks/","example":"Can you eat noodles using wooden chopsticks?","exampleVi":"Bạn có thể ăn mì bằng đũa gỗ được không?","audio":"vocab-audio/flyers/160.mp3"},{"en":"dangerous","vi":"nguy hiểm","art":"2622","ipa":"/ˈdeɪn.dʒər.əs/","example":"It is dangerous to touch broken glass with bare hands.","exampleVi":"Rất nguy hiểm nếu chạm vào kính vỡ bằng tay trần.","audio":"vocab-audio/flyers/161.mp3"},{"en":"delicious","vi":"ngon","art":"1f60b","ipa":"/dɪˈlɪʃ.əs/","example":"The chef prepared a delicious meal of roast chicken.","exampleVi":"Đầu bếp đã chuẩn bị một bữa ăn ngon miệng với món gà nướng.","audio":"vocab-audio/flyers/162.mp3"},{"en":"excited","vi":"hào hứng","art":"1f929","ipa":"/ɪkˈsaɪ.tɪd/","example":"The children were excited about visiting the castle.","exampleVi":"Các bạn nhỏ rất hào hứng về chuyến tham quan lâu đài.","audio":"vocab-audio/flyers/163.mp3"},{"en":"feel","vi":"cảm thấy","art":"2764","ipa":"/fiːl/","example":"I feel happy whenever I listen to my favourite music.","exampleVi":"Tôi cảm thấy vui vẻ mỗi khi nghe bản nhạc yêu thích.","audio":"vocab-audio/flyers/164.mp3"},{"en":"finish","vi":"hoàn thành","art":"1f3c1","ipa":"/ˈfɪn.ɪʃ/","example":"You must finish your project before Friday afternoon.","exampleVi":"Bạn phải hoàn thành dự án trước chiều thứ Sáu.","audio":"vocab-audio/flyers/165.mp3"},{"en":"flour","vi":"bột mì","art":"1f35e","ipa":"/flaʊər/","example":"We need two cups of white flour to bake the cake.","exampleVi":"Chúng ta cần hai cốc bột mì trắng để nướng chiếc bánh.","audio":"vocab-audio/flyers/166.mp3"},{"en":"fork","vi":"cái nĩa","art":"1f374","ipa":"/fɔːk/","example":"Eat your pasta with a spoon and a fork.","exampleVi":"Hãy ăn món mì Ý của bạn bằng một chiếc thìa và một cái nĩa.","audio":"vocab-audio/flyers/167.mp3"},{"en":"frightened","vi":"sợ hãi","art":"1f631","ipa":"/ˈfraɪ.tənd/","example":"The sudden thunder made the small puppy frightened.","exampleVi":"Tiếng sấm sét bất ngờ đã khiến chú cún con sợ hãi.","audio":"vocab-audio/flyers/168.mp3"},{"en":"group","vi":"nhóm","art":"1f465","ipa":"/ɡruːp/","example":"A group of pupils worked together on the science project.","exampleVi":"Một nhóm học sinh đã cùng nhau làm dự án khoa học.","audio":"vocab-audio/flyers/169.mp3"},{"en":"hard","vi":"cứng, khó","art":"1faa8","ipa":"/hɑːd/","example":"He studied hard and passed all his school tests.","exampleVi":"Cậu ấy đã học tập chăm chỉ và vượt qua mọi bài kiểm tra ở trường.","audio":"vocab-audio/flyers/170.mp3"},{"en":"hear","vi":"nghe thấy","art":"1f442","ipa":"/hɪər/","example":"I could hear the gentle sound of the waterfall nearby.","exampleVi":"Tôi có thể nghe thấy âm thanh êm dịu của thác nước gần đó.","audio":"vocab-audio/flyers/171.mp3"},{"en":"honey","vi":"mật ong","art":"1f36f","ipa":"/ˈhʌn.i/","example":"She likes adding sweet honey to her morning cup of tea.","exampleVi":"Cô ấy thích thêm mật ong ngọt ngào vào tách trà buổi sáng.","audio":"vocab-audio/flyers/172.mp3"},{"en":"ill","vi":"ốm","art":"1f912","ipa":"/ɪl/","example":"He missed three days of school because he was ill.","exampleVi":"Cậu ấy đã nghỉ học ba ngày vì bị ốm.","audio":"vocab-audio/flyers/173.mp3"},{"en":"jam","vi":"mứt","art":"1f96b","ipa":"/dʒæm/","example":"I spread sweet strawberry jam on my toast for breakfast.","exampleVi":"Tôi quết mứt dâu tây ngọt lên bánh mì nướng cho bữa sáng.","audio":"vocab-audio/flyers/174.mp3"},{"en":"knife","vi":"dao","art":"1f52a","ipa":"/naɪf/","example":"Use a sharp knife carefully to cut the watermelon.","exampleVi":"Hãy dùng con dao sắc một cách cẩn thận để cắt quả dưa hấu.","audio":"vocab-audio/flyers/175.mp3"},{"en":"look like","vi":"trông giống","art":"1f440","ipa":"/lʊk laɪk/","example":"Those fluffy white clouds look like cute sheep.","exampleVi":"Những đám mây trắng bồng bềnh kia trông giống như những chú cừu dễ thương.","audio":"vocab-audio/flyers/176.mp3"},{"en":"lovely","vi":"đáng yêu","art":"1f970","ipa":"/ˈlʌv.li/","example":"Thank you for inviting us to such a lovely party.","exampleVi":"Cảm ơn bạn đã mời chúng tôi đến một bữa tiệc đáng yêu như vậy.","audio":"vocab-audio/flyers/177.mp3"},{"en":"medicine","vi":"thuốc","art":"1f48a","ipa":"/ˈmed.sən/","example":"Take this medicine three times a day after meals.","exampleVi":"Hãy uống loại thuốc này ba lần mỗi ngày sau các bữa ăn.","audio":"vocab-audio/flyers/178.mp3"},{"en":"mind","vi":"để ý, phiền","art":"1f9e0","ipa":"/maɪnd/","example":"Do you mind if I open the classroom window?","exampleVi":"Bạn có để ý phiền lòng không nếu tôi mở cửa sổ lớp học?","audio":"vocab-audio/flyers/179.mp3"},{"en":"olives","vi":"quả ô liu","art":"1fad2","ipa":"/ˈɒl.ɪvz/","example":"My father likes putting black olives on his pizza.","exampleVi":"Bố tôi thích cho những quả ô liu đen lên bánh pizza của mình.","audio":"vocab-audio/flyers/180.mp3"},{"en":"pepper","vi":"hạt tiêu","art":"1fad1","ipa":"/ˈpep.ər/","example":"Add a little black pepper to the hot soup.","exampleVi":"Hãy cho thêm một ít hạt tiêu đen vào bát súp nóng.","audio":"vocab-audio/flyers/181.mp3"},{"en":"piece","vi":"mảnh, miếng","art":"1f9e9","ipa":"/piːs/","example":"Would you like a piece of homemade chocolate cake?","exampleVi":"Bạn có muốn ăn một miếng bánh sô-cô-la nhà làm không?","audio":"vocab-audio/flyers/182.mp3"},{"en":"pizza","vi":"bánh pizza","art":"1f355","ipa":"/ˈpiːt.sə/","example":"We ordered a large cheese and tomato pizza for dinner.","exampleVi":"Chúng tôi đã gọi một chiếc bánh pizza phô mai và cà chua lớn cho bữa tối.","audio":"vocab-audio/flyers/183.mp3"},{"en":"salt","vi":"muối","art":"1f9c2","ipa":"/sɒlt/","example":"There was too much salt in the vegetable soup.","exampleVi":"Có quá nhiều muối trong món súp rau củ.","audio":"vocab-audio/flyers/184.mp3"},{"en":"smell","vi":"mùi, ngửi","art":"1f443","ipa":"/smel/","example":"The sweet smell of freshly baked bread filled the kitchen.","exampleVi":"Mùi thơm ngọt ngào của bánh mì mới nướng lan tỏa khắp gian bếp.","audio":"vocab-audio/flyers/185.mp3"},{"en":"soft","vi":"mềm","art":"1f9f8","ipa":"/sɒft/","example":"The cat curled up to sleep on the soft cushion.","exampleVi":"Con mèo cuộn tròn ngủ trên chiếc gối tựa mềm mại.","audio":"vocab-audio/flyers/186.mp3"},{"en":"sound","vi":"âm thanh","art":"1f50a","ipa":"/saʊnd/","example":"The strange sound came from the top of the old tree.","exampleVi":"Âm thanh kỳ lạ phát ra từ phần trên cùng của cái cây cổ thụ.","audio":"vocab-audio/flyers/187.mp3"},{"en":"spend","vi":"tiêu, dành","art":"1f4b8","ipa":"/spend/","example":"How much money did you spend on those souvenirs?","exampleVi":"Bạn đã tiêu bao nhiêu tiền vào những món đồ lưu niệm đó?","audio":"vocab-audio/flyers/188.mp3"},{"en":"spoon","vi":"cái thìa","art":"1f944","ipa":"/spuːn/","example":"Stir your hot tea gently with a small silver spoon.","exampleVi":"Hãy khuấy tách trà nóng nhẹ nhàng bằng một cái thìa bạc nhỏ.","audio":"vocab-audio/flyers/189.mp3"},{"en":"strawberry","vi":"dâu tây","art":"1f353","ipa":"/ˈstrɔː.bər.i/","example":"She picked a ripe red strawberry from the garden.","exampleVi":"Cô ấy đã hái một quả dâu tây đỏ chín mọng từ trong vườn.","audio":"vocab-audio/flyers/190.mp3"},{"en":"sugar","vi":"đường ăn","art":"1f36c","ipa":"/ˈʃʊɡ.ər/","example":"Eating too much sugar is harmful to your teeth.","exampleVi":"Ăn quá nhiều đường ăn sẽ có hại cho răng của bạn.","audio":"vocab-audio/flyers/191.mp3"},{"en":"surprise","vi":"điều bất ngờ","art":"1f632","ipa":"/səˈpraɪz/","example":"The surprise birthday present made her smile happily.","exampleVi":"Món quà sinh nhật đầy bất ngờ đã khiến cô ấy mỉm cười hạnh phúc.","audio":"vocab-audio/flyers/192.mp3"},{"en":"tastes","vi":"có vị","art":"1f445","ipa":"/teɪsts/","example":"This homemade ice cream tastes sweet and refreshing.","exampleVi":"Món kem nhà làm này có vị ngọt và thanh mát.","audio":"vocab-audio/flyers/193.mp3"},{"en":"tortoise","vi":"rùa cạn","art":"1f422","ipa":"/ˈtɔː.təs/","example":"A land tortoise walks much slower than a rabbit.","exampleVi":"Một con rùa cạn đi bộ chậm hơn nhiều so với một con thỏ.","audio":"vocab-audio/flyers/194.mp3"},{"en":"visit","vi":"thăm","art":"1f3e0","ipa":"/ˈvɪz.ɪt/","example":"We plan to visit the historic castle during the holidays.","exampleVi":"Chúng tôi dự định đến thăm lâu đài lịch sử trong kỳ nghỉ.","audio":"vocab-audio/flyers/195.mp3"},{"en":"wool","vi":"len","art":"1f9f6","ipa":"/wʊl/","example":"This warm winter scarf is made of natural wool.","exampleVi":"Chiếc khăn quàng mùa đông ấm áp này được làm từ len tự nhiên.","audio":"vocab-audio/flyers/196.mp3"},{"en":"yoghurt","vi":"sữa chua","art":"1f95b","ipa":"/ˈjɒɡ.ət/","example":"I eat fresh yoghurt with fruit every morning.","exampleVi":"Tôi ăn sữa chua tươi với hoa quả vào mỗi buổi sáng.","audio":"vocab-audio/flyers/197.mp3"}],"art":"1f355"},{"id":"4","title":"At school","words":[{"en":"a.m.","vi":"buổi sáng (giờ)","art":"1f305","ipa":"/ˌeɪˈem/","example":"Our first school lesson starts at eight a.m. sharp.","exampleVi":"Tiết học đầu tiên của chúng tôi bắt đầu vào đúng tám giờ buổi sáng.","audio":"vocab-audio/flyers/198.mp3"},{"en":"actually","vi":"thực ra","art":"1f914","ipa":"/ˈæk.tʃu.ə.li/","example":"I thought the exam would be hard, but actually it was easy.","exampleVi":"Tôi từng nghĩ kỳ thi sẽ khó, nhưng thực ra nó lại rất dễ.","audio":"vocab-audio/flyers/199.mp3"},{"en":"agree","vi":"đồng ý","art":"1f91d","ipa":"/əˈɡriː/","example":"We all agree that reading books is good for our knowledge.","exampleVi":"Tất cả chúng tôi đều đồng ý rằng đọc sách rất tốt cho kiến thức.","audio":"vocab-audio/flyers/200.mp3"},{"en":"art","vi":"mỹ thuật","art":"1f3a8","ipa":"/ɑːt/","example":"We painted beautiful watercolours in our art class today.","exampleVi":"Hôm nay chúng tôi đã vẽ màu nước rất đẹp trong lớp mỹ thuật.","audio":"vocab-audio/flyers/201.mp3"},{"en":"beetle","vi":"bọ cánh cứng","art":"1fab2","ipa":"/ˈbiː.tl/","example":"The shiny black beetle crawled slowly across the path.","exampleVi":"Con bọ cánh cứng màu đen bóng bò chậm chạp qua lối đi.","audio":"vocab-audio/flyers/202.mp3"},{"en":"card","vi":"tấm thiệp","art":"1f0cf","ipa":"/kɑːd/","example":"I made a handmade birthday card for my best friend.","exampleVi":"Tôi đã tự tay làm một tấm thiệp sinh nhật cho bạn thân nhất.","audio":"vocab-audio/flyers/203.mp3"},{"en":"club","vi":"câu lạc bộ","art":"2663","ipa":"/klʌb/","example":"She joined the chess club to improve her concentration.","exampleVi":"Cô ấy đã tham gia câu lạc bộ cờ vua để nâng cao khả năng tập trung.","audio":"vocab-audio/flyers/204.mp3"},{"en":"cut","vi":"cắt","art":"2702","ipa":"/kʌt/","example":"Please cut the coloured paper into four equal pieces.","exampleVi":"Làm ơn hãy cắt tờ giấy màu thành bốn mảnh bằng nhau.","audio":"vocab-audio/flyers/205.mp3"},{"en":"dictionary","vi":"từ điển","art":"1f4d5","ipa":"/ˈdɪk.ʃən.ər.i/","example":"Look up the meaning of unfamiliar words in this dictionary.","exampleVi":"Hãy tra cứu nghĩa của các từ lạ trong cuốn từ điển này.","audio":"vocab-audio/flyers/206.mp3"},{"en":"disappear","vi":"biến mất","art":"1f47b","ipa":"/ˌdɪs.əˈpɪər/","example":"The rabbit seemed to disappear into the magician's hat.","exampleVi":"Chú thỏ dường như đã biến mất vào trong chiếc mũ của nhà ảo thuật.","audio":"vocab-audio/flyers/207.mp3"},{"en":"during","vi":"trong suốt","art":"23f3","ipa":"/ˈdʒʊə.rɪŋ/","example":"We are not allowed to talk during the English examination.","exampleVi":"Chúng tôi không được phép nói chuyện trong suốt kỳ thi tiếng Anh.","audio":"vocab-audio/flyers/208.mp3"},{"en":"enormous","vi":"khổng lồ","art":"1f418","ipa":"/ɪˈnɔː.məs/","example":"An enormous spaceship landed silently in the science fiction movie.","exampleVi":"Một con tàu vũ trụ khổng lồ đã hạ cánh êm đềm trong bộ phim khoa học viễn tưởng.","audio":"vocab-audio/flyers/209.mp3"},{"en":"excellent","vi":"xuất sắc","art":"1f4af","ipa":"/ˈek.səl.ənt/","example":"The teacher praised him for his excellent presentation on animals.","exampleVi":"Thầy giáo đã khen ngợi cậu ấy vì bài thuyết trình xuất sắc về các loài động vật.","audio":"vocab-audio/flyers/210.mp3"},{"en":"geography","vi":"địa lý","art":"1f30d","ipa":"/dʒiˈɒɡ.rə.fi/","example":"We learned about rivers, mountains, and deserts in geography.","exampleVi":"Chúng tôi đã học về các con sông, ngọn núi và sa mạc trong môn địa lý.","audio":"vocab-audio/flyers/211.mp3"},{"en":"half","vi":"một nửa","art":"1f313","ipa":"/hɑːf/","example":"The first half of the match ended with a score of one-one.","exampleVi":"Một nửa đầu của trận đấu đã kết thúc với tỷ số một đều.","audio":"vocab-audio/flyers/212.mp3"},{"en":"history","vi":"lịch sử","art":"1f3db","ipa":"/ˈhɪs.tər.i/","example":"Our history teacher told us fascinating facts about the castle.","exampleVi":"Giáo viên lịch sử đã kể cho chúng tôi những sự thật hấp dẫn về lâu đài.","audio":"vocab-audio/flyers/213.mp3"},{"en":"improve","vi":"cải thiện","art":"1f4c8","ipa":"/ɪmˈpruːv/","example":"Practising every day will help you improve your English skills.","exampleVi":"Luyện tập mỗi ngày sẽ giúp bạn cải thiện các kỹ năng tiếng Anh.","audio":"vocab-audio/flyers/214.mp3"},{"en":"information","vi":"thông tin","art":"2139","ipa":"/ˌɪn.fəˈmeɪ.ʃən/","example":"You can find useful information about universities online.","exampleVi":"Bạn có thể tìm thấy nhiều thông tin hữu ích về các trường đại học trên mạng.","audio":"vocab-audio/flyers/215.mp3"},{"en":"invitation","vi":"lời mời","art":"1f4e9","ipa":"/ˌɪn.vɪˈteɪ.ʃən/","example":"I received an invitation to attend the school awards ceremony.","exampleVi":"Tôi đã nhận được một lời mời tham dự lễ trao giải của trường.","audio":"vocab-audio/flyers/216.mp3"},{"en":"IT","vi":"công nghệ thông tin","art":"1f4e6","ipa":"/ˌaɪˈtiː/","example":"Students learn how to code websites in their IT lessons.","exampleVi":"Học sinh học cách lập trình trang web trong các tiết công nghệ thông tin.","audio":"vocab-audio/flyers/217.mp3"},{"en":"join","vi":"tham gia","ipa":"/dʒɔɪn/","example":"Would you like to join our study group this afternoon?","exampleVi":"Bạn có muốn tham gia nhóm học tập của chúng tôi vào chiều nay không?","audio":"vocab-audio/flyers/218.mp3"},{"en":"language","vi":"ngôn ngữ","art":"1f5e3","ipa":"/ˈlæŋ.ɡwɪdʒ/","example":"English is an international language spoken all around the world.","exampleVi":"Tiếng Anh là ngôn ngữ quốc tế được nói trên toàn thế giới.","audio":"vocab-audio/flyers/219.mp3"},{"en":"maths","vi":"môn toán","art":"1f522","ipa":"/mæθs/","example":"He solves difficult problem in maths very quickly.","exampleVi":"Cậu ấy giải các bài toán khó trong môn toán rất nhanh chóng.","audio":"vocab-audio/flyers/220.mp3"},{"en":"metal","vi":"kim loại","art":"1f9ff","ipa":"/ˈmet.əl/","example":"The heavy key was made of strong, silver-coloured metal.","exampleVi":"Chiếc chìa khóa nặng được làm bằng kim loại chắc chắn màu ánh bạc.","audio":"vocab-audio/flyers/221.mp3"},{"en":"midday","vi":"giữa trưa","art":"2600","ipa":"/ˌmɪdˈdeɪ/","example":"The sun was high in the sky and extremely hot at midday.","exampleVi":"Mặt trời lên cao trên bầu trời và cực kỳ nóng bức vào giữa trưa.","audio":"vocab-audio/flyers/222.mp3"},{"en":"midnight","vi":"nửa đêm","art":"1f319","ipa":"/ˈmɪd.naɪt/","example":"The film ended at midnight and everyone went to sleep.","exampleVi":"Bộ phim kết thúc lúc nửa đêm và mọi người đều đi ngủ.","audio":"vocab-audio/flyers/223.mp3"},{"en":"music","vi":"âm nhạc","art":"1f3b5","ipa":"/ˈmjuː.zɪk/","example":"Classical music helps students feel calm and focused.","exampleVi":"Âm nhạc cổ điển giúp học sinh cảm thấy bình tĩnh và tập trung.","audio":"vocab-audio/flyers/224.mp3"},{"en":"o’clock","vi":"giờ đúng","art":"1f55b","ipa":"/əˈklɒk/","example":"Our school lessons start promptly at eight o’clock.","exampleVi":"Các tiết học ở trường của chúng tôi bắt đầu đúng tám giờ đúng.","audio":"vocab-audio/flyers/225.mp3"},{"en":"p.m.","vi":"buổi chiều, tối (giờ)","art":"1f303","ipa":"/ˌpiːˈem/","example":"The school library closes at five p.m. every weekday.","exampleVi":"Thư viện trường đóng cửa vào lúc năm giờ chiều mỗi ngày trong tuần.","audio":"vocab-audio/flyers/226.mp3"},{"en":"plastic","vi":"nhựa","art":"1f964","ipa":"/ˈplæs.tɪk/","example":"Try to reduce using plastic bags to protect the environment.","exampleVi":"Hãy cố gắng giảm sử dụng túi nhựa để bảo vệ môi trường.","audio":"vocab-audio/flyers/227.mp3"},{"en":"platform","vi":"sân ga, bục","art":"1f686","ipa":"/ˈplæt.fɔːm/","example":"The train to London departs from platform number four.","exampleVi":"Chuyến tàu đi Luân Đôn khởi hành từ sân ga số bốn.","audio":"vocab-audio/flyers/228.mp3"},{"en":"program","vi":"chương trình máy tính","art":"1f4bb","ipa":"/ˈprəʊ.ɡræm/","example":"He wrote a computer program to calculate maths problems.","exampleVi":"Cậu ấy đã viết một chương trình máy tính để giải các bài toán.","audio":"vocab-audio/flyers/229.mp3"},{"en":"quarter","vi":"một phần tư","art":"1f553","ipa":"/ˈkwɔː.tər/","example":"It is a quarter past three, so our lesson is finished.","exampleVi":"Bây giờ là ba giờ mười lăm phút (qua một phần tư), nên tiết học đã xong.","audio":"vocab-audio/flyers/230.mp3"},{"en":"repeat","vi":"nhắc lại","art":"1f501","ipa":"/rɪˈpiːt/","example":"Could you please repeat that question more slowly?","exampleVi":"Thầy có thể vui lòng nhắc lại câu hỏi đó chậm hơn được không ạ?","audio":"vocab-audio/flyers/231.mp3"},{"en":"same","vi":"giống nhau","art":"267e","ipa":"/seɪm/","example":"The twins were wearing the same blue school uniform.","exampleVi":"Hai đứa trẻ sinh đôi đang mặc đồng phục học sinh màu xanh giống nhau.","audio":"vocab-audio/flyers/232.mp3"},{"en":"save","vi":"lưu, tiết kiệm","art":"1f4be","ipa":"/seɪv/","example":"Remember to save your documents before closing your laptop.","exampleVi":"Hãy nhớ lưu các tài liệu của bạn trước khi gập máy tính xách tay lại.","audio":"vocab-audio/flyers/233.mp3"},{"en":"science","vi":"khoa học","art":"1f52c","ipa":"/ˈsaɪ.əns/","example":"We did an exciting experiment in the science laboratory.","exampleVi":"Chúng tôi đã làm một thí nghiệm hào hứng trong phòng thí nghiệm khoa học.","audio":"vocab-audio/flyers/234.mp3"},{"en":"study","vi":"học tập","art":"1f4da","ipa":"/ˈstʌd.i/","example":"She wants to study medicine at university in the future.","exampleVi":"Cô ấy muốn học tập ngành y tại trường đại học trong tương lai.","audio":"vocab-audio/flyers/235.mp3"},{"en":"subject","vi":"môn học","art":"1f4d6","ipa":"/ˈsʌb.dʒɪkt/","example":"Science is my favourite school subject because I love nature.","exampleVi":"Khoa học là môn học yêu thích nhất của tôi vì tôi yêu thiên nhiên.","audio":"vocab-audio/flyers/236.mp3"},{"en":"sure","vi":"chắc chắn","art":"1f44d","ipa":"/ʃɔːr/","example":"Are you sure you have packed your passport in your bag?","exampleVi":"Bạn có chắc chắn là bạn đã cất hộ chiếu vào túi xách chưa?","audio":"vocab-audio/flyers/237.mp3"},{"en":"timetable","vi":"thời khóa biểu","art":"1f4c5","ipa":"/ˈtaɪmˌteɪ.bl/","example":"Check your school timetable to see which books you need.","exampleVi":"Hãy kiểm tra thời khóa biểu của trường để xem bạn cần mang những cuốn sách nào.","audio":"vocab-audio/flyers/238.mp3"},{"en":"quiz","vi":"bài đố","art":"2753","ipa":"/kwɪz/","example":"Our teacher prepared a fun quiz on world geography.","exampleVi":"Cô giáo chúng tôi đã chuẩn bị một bài đố vui về địa lý thế giới.","audio":"vocab-audio/flyers/239.mp3"}],"art":"1f52c"},{"id":"R1","title":"Revision 1","words":[{"en":"believe","vi":"tin tưởng","art":"1f607","ipa":"/bɪˈliːv/","example":"I believe that hard work always brings success.","exampleVi":"Tôi tin tưởng rằng sự chăm chỉ sẽ luôn mang lại thành công.","audio":"vocab-audio/flyers/240.mp3"},{"en":"minute","vi":"phút","art":"23f1","ipa":"/ˈmɪn.ɪt/","example":"Please wait a minute while I fetch my sports jacket.","exampleVi":"Làm ơn hãy đợi một phút trong khi tôi đi lấy chiếc áo khoác thể thao.","audio":"vocab-audio/flyers/241.mp3"},{"en":"mix","vi":"trộn","art":"1f963","ipa":"/mɪks/","example":"Mix the eggs and flour together until the batter is smooth.","exampleVi":"Hãy trộn trứng và bột mì cùng nhau cho đến khi bột thật mịn.","audio":"vocab-audio/flyers/242.mp3"},{"en":"turn on","vi":"bật lên","art":"1f4a1","ipa":"/tɜːn ɒn/","example":"Please turn on the light because the room is too dark.","exampleVi":"Làm ơn hãy bật đèn lên vì căn phòng quá tối.","audio":"vocab-audio/flyers/243.mp3"},{"en":"until","vi":"cho đến khi","art":"23f3","ipa":"/ənˈtɪl/","example":"We waited at the railway station until the rain finally stopped.","exampleVi":"Chúng tôi đã đợi ở nhà ga cho đến khi cơn mưa cuối cùng cũng tạnh.","audio":"vocab-audio/flyers/244.mp3"},{"en":"without","vi":"không có","art":"274c","ipa":"/wɪˈðaʊt/","example":"You cannot enter the theatre without showing your ticket.","exampleVi":"Bạn không thể vào nhà hát mà không có vé xuất trình.","audio":"vocab-audio/flyers/245.mp3"}],"art":"1f3c6"},{"id":"5","title":"A day out","words":[{"en":"act","vi":"diễn","art":"1f3ad","ipa":"/ækt/","example":"The young actors act very well in the school play.","exampleVi":"Các diễn viên trẻ diễn xuất rất tốt trong vở kịch của trường.","audio":"vocab-audio/flyers/246.mp3"},{"en":"actor","vi":"diễn viên","art":"1f3ad","ipa":"/ˈæk.tər/","example":"The famous actor signed autographs for his fans.","exampleVi":"Người diễn viên nổi tiếng đã ký tặng cho người hâm mộ của mình.","audio":"vocab-audio/flyers/247.mp3"},{"en":"ago","vi":"cách đây","art":"23ea","ipa":"/əˈɡəʊ/","example":"Dinosaurs lived on Earth millions of years ago.","exampleVi":"Khủng long đã sống trên Trái Đất hàng triệu năm cách đây.","audio":"vocab-audio/flyers/248.mp3"},{"en":"air","vi":"không khí","art":"1f4a8","ipa":"/eər/","example":"The fresh mountain air was cool and crisp.","exampleVi":"Bầu không khí trong lành miền núi thật mát mẻ và sảng khoái.","audio":"vocab-audio/flyers/249.mp3"},{"en":"also","vi":"cũng","art":"2795","ipa":"/ˈɔːl.səʊ/","example":"She speaks English fluently and also knows French.","exampleVi":"Cô ấy nói tiếng Anh trôi chảy và cũng biết tiếng Pháp nữa.","audio":"vocab-audio/flyers/250.mp3"},{"en":"brave","vi":"dũng cảm","art":"1f981","ipa":"/breɪv/","example":"The brave firefighter entered the burning building.","exampleVi":"Người lính cứu hỏa dũng cảm đã đi vào tòa nhà đang cháy.","audio":"vocab-audio/flyers/251.mp3"},{"en":"cage","vi":"lồng","art":"1f5d3","ipa":"/keɪdʒ/","example":"The tiger was resting peacefully inside its spacious cage.","exampleVi":"Con hổ đang nghỉ ngơi thanh bình bên trong chiếc lồng rộng rãi.","audio":"vocab-audio/flyers/252.mp3"},{"en":"cartoon","vi":"phim hoạt hình","art":"1f3a8","ipa":"/kɑːˈtuːn/","example":"Children love watching funny cartoons on Saturday mornings.","exampleVi":"Trẻ em rất thích xem phim hoạt hình vui nhộn vào các buổi sáng thứ Bảy.","audio":"vocab-audio/flyers/253.mp3"},{"en":"cereal","vi":"ngũ cốc","art":"1f963","ipa":"/ˈsɪə.ri.əl/","example":"I usually have a bowl of cereal with fresh milk.","exampleVi":"Tôi thường ăn một bát ngũ cốc với sữa tươi.","audio":"vocab-audio/flyers/254.mp3"},{"en":"cheap","vi":"rẻ","art":"1fa99","ipa":"/tʃiːp/","example":"The entrance tickets to the museum were quite cheap.","exampleVi":"Vé vào cửa bảo tàng khá rẻ.","audio":"vocab-audio/flyers/255.mp3"},{"en":"cinema","vi":"rạp chiếu phim","art":"1f3ac","ipa":"/ˈsɪn.ə.mɑː/","example":"Let's go to the cinema to watch the new superhero movie.","exampleVi":"Chúng ta hãy đến rạp chiếu phim để xem bộ phim siêu anh hùng mới nhé.","audio":"vocab-audio/flyers/256.mp3"},{"en":"circus","vi":"rạp xiếc","art":"1f3aa","ipa":"/ˈsɜː.kəs/","example":"We enjoyed the acrobats performing high above at the circus.","exampleVi":"Chúng tôi rất thích các diễn viên xiếc biểu diễn trên cao ở rạp xiếc.","audio":"vocab-audio/flyers/257.mp3"},{"en":"clown","vi":"chú hề","art":"1f921","ipa":"/klaʊn/","example":"The funny clown made everyone laugh with his tricks.","exampleVi":"Chú hề vui tính đã làm mọi người bật cười với những trò diễn của mình.","audio":"vocab-audio/flyers/258.mp3"},{"en":"dinosaurs","vi":"khủng long","art":"1f996","ipa":"/ˈdaɪ.nə.sɔːz/","example":"Dinosaurs were enormous creatures that roamed the Earth.","exampleVi":"Khủng long từng là những sinh vật khổng lồ lang thang trên Trái Đất.","audio":"vocab-audio/flyers/259.mp3"},{"en":"extinct","vi":"tuyệt chủng","art":"1f9a4","ipa":"/ɪkˈstɪŋkt/","example":"Many ancient species became extinct because of climate change.","exampleVi":"Nhiều loài cổ xưa đã bị tuyệt chủng do biến đổi khí hậu.","audio":"vocab-audio/flyers/260.mp3"},{"en":"find out","vi":"tìm hiểu","art":"1f50d","ipa":"/faɪnd aʊt/","example":"We visited the library to find out more about the planets.","exampleVi":"Chúng tôi đã đến thư viện để tìm hiểu thêm về các hành tinh.","audio":"vocab-audio/flyers/261.mp3"},{"en":"frightening","vi":"đáng sợ","art":"1f631","ipa":"/ˈfraɪ.tən.ɪŋ/","example":"The loud thunder during the midnight storm was frightening.","exampleVi":"Tiếng sấm lớn trong cơn bão nửa đêm thật đáng sợ.","audio":"vocab-audio/flyers/262.mp3"},{"en":"gym","vi":"phòng tập","art":"1f4aa","ipa":"/dʒɪm/","example":"Pupils play basketball and do exercise in the school gym.","exampleVi":"Học sinh chơi bóng rổ và tập thể dục trong phòng tập của trường.","audio":"vocab-audio/flyers/263.mp3"},{"en":"hate","vi":"ghét","art":"1f621","ipa":"/heɪt/","example":"I hate waking up early when it is freezing outside.","exampleVi":"Tôi ghét phải thức dậy sớm khi ngoài trời đang giá lạnh.","audio":"vocab-audio/flyers/264.mp3"},{"en":"high","vi":"cao","art":"2b06","ipa":"/haɪ/","example":"The eagle flew high above the mountain peaks.","exampleVi":"Con đại bàng bay cao phía trên các đỉnh núi.","audio":"vocab-audio/flyers/265.mp3"},{"en":"hole","vi":"cái lỗ","art":"1f573","ipa":"/həʊl/","example":"The rabbit quickly disappeared into a hole in the ground.","exampleVi":"Chú thỏ nhanh chóng biến mất vào một cái lỗ trên mặt đất.","audio":"vocab-audio/flyers/266.mp3"},{"en":"hour","vi":"giờ","art":"23f0","ipa":"/aʊər/","example":"The football match lasted for more than an hour.","exampleVi":"Trận đấu bóng đá kéo dài hơn một giờ đồng hồ.","audio":"vocab-audio/flyers/267.mp3"},{"en":"million","vi":"một triệu","art":"1f4b0","ipa":"/ˈmɪl.jən/","example":"Dinosaurs died out around sixty-six million years ago.","exampleVi":"Khủng long đã tuyệt chủng khoảng sáu mươi sáu triệu năm trước.","audio":"vocab-audio/flyers/268.mp3"},{"en":"museum","vi":"bảo tàng","art":"1f3db","ipa":"/mjuːˈziː.əm/","example":"The history museum houses ancient royal crowns and jewels.","exampleVi":"Bảo tàng lịch sử lưu giữ những chiếc vương miện và châu báu hoàng gia cổ.","audio":"vocab-audio/flyers/269.mp3"},{"en":"ocean","vi":"đại dương","art":"1f30a","ipa":"/ˈəʊ.ʃən/","example":"Whales travel thousands of kilometres across the blue ocean.","exampleVi":"Cá voi di chuyển hàng nghìn ki-lô-mét qua đại dương xanh.","audio":"vocab-audio/flyers/270.mp3"},{"en":"pleased","vi":"hài lòng","art":"1f604","ipa":"/pliːzd/","example":"The teacher was pleased with our high test scores.","exampleVi":"Thầy giáo rất hài lòng với điểm số bài kiểm tra cao của chúng tôi.","audio":"vocab-audio/flyers/271.mp3"},{"en":"project","vi":"dự án","art":"1f4c1","ipa":"/ˈprɒdʒ.ekt/","example":"Our science project is about protecting endangered animals.","exampleVi":"Dự án khoa học của chúng tôi là về việc bảo vệ các loài động vật có nguy cơ tuyệt chủng.","audio":"vocab-audio/flyers/272.mp3"},{"en":"pyramids","vi":"kim tự tháp","art":"1f3dc","ipa":"/ˈpɪr.ə.mɪdz/","example":"The ancient pyramids in Egypt were built thousands of years ago.","exampleVi":"Những kim tự tháp cổ đại ở Ai Cập được xây dựng từ hàng nghìn năm trước.","audio":"vocab-audio/flyers/273.mp3"},{"en":"screen","vi":"màn hình","art":"1f5a5","ipa":"/skriːn/","example":"The movie was projected onto an enormous cinema screen.","exampleVi":"Bộ phim được chiếu lên một màn hình rạp chiếu bóng khổng lồ.","audio":"vocab-audio/flyers/274.mp3"},{"en":"seat","vi":"chỗ ngồi","art":"1fa91","ipa":"/siːt/","example":"Please return to your seat before the performance starts.","exampleVi":"Làm ơn hãy trở về chỗ ngồi của bạn trước khi buổi diễn bắt đầu.","audio":"vocab-audio/flyers/275.mp3"},{"en":"sell","vi":"bán","art":"1f3ea","ipa":"/sel/","example":"They sell fresh bread and sweet biscuits at the bakery.","exampleVi":"Họ bán bánh mì tươi và bánh quy ngọt tại tiệm bánh.","audio":"vocab-audio/flyers/276.mp3"},{"en":"several","vi":"một vài","art":"1f522","ipa":"/ˈsev.ər.əl/","example":"She has read several books on space exploration this month.","exampleVi":"Cô ấy đã đọc một vài cuốn sách về khám phá không gian trong tháng này.","audio":"vocab-audio/flyers/277.mp3"},{"en":"special","vi":"đặc biệt","art":"2728","ipa":"/ˈspeʃ.əl/","example":"We prepared a special dinner to celebrate Grandpa's birthday.","exampleVi":"Chúng tôi đã chuẩn bị một bữa tối đặc biệt để mừng sinh nhật của ông.","audio":"vocab-audio/flyers/278.mp3"},{"en":"stage","vi":"sân khấu","art":"1f3df","ipa":"/steɪdʒ/","example":"The actors came onto the brightly lit stage.","exampleVi":"Các diễn viên bước ra sân khấu ngập tràn ánh đèn sáng rực.","audio":"vocab-audio/flyers/279.mp3"},{"en":"stay","vi":"ở lại","art":"1f3e0","ipa":"/steɪ/","example":"We decided to stay in a hotel near the beach.","exampleVi":"Chúng tôi đã quyết định ở lại một khách sạn gần bãi biển.","audio":"vocab-audio/flyers/280.mp3"},{"en":"swing","vi":"đu đưa","art":"1fa81","ipa":"/swɪŋ/","example":"Children enjoy sitting on the wooden swing in the park.","exampleVi":"Trẻ em thích ngồi đu đưa trên chiếc xích đu gỗ ở công viên.","audio":"vocab-audio/flyers/281.mp3"},{"en":"telephone","vi":"điện thoại","art":"1f4de","ipa":"/ˈtel.ɪ.fəʊn/","example":"Please answer the telephone, it has been ringing for a minute.","exampleVi":"Làm ơn hãy trả lời điện thoại, chuông đã reo cả phút rồi.","audio":"vocab-audio/flyers/282.mp3"},{"en":"theatre","vi":"nhà hát","art":"1f3ac","ipa":"/ˈθɪə.tər/","example":"We watched a wonderful musical performance at the city theatre.","exampleVi":"Chúng tôi đã xem một vở nhạc kịch tuyệt vời tại nhà hát thành phố.","audio":"vocab-audio/flyers/283.mp3"},{"en":"tomorrow","vi":"ngày mai","art":"1f4c5","ipa":"/təˈmɒr.əʊ/","example":"Our school will hold the annual sports day tomorrow.","exampleVi":"Trường chúng tôi sẽ tổ chức ngày hội thể thao thường niên vào ngày mai.","audio":"vocab-audio/flyers/284.mp3"},{"en":"tune","vi":"giai điệu","art":"1f3b5","ipa":"/tʃuːn/","example":"The band played a catchy, cheerful tune that everyone loved.","exampleVi":"Ban nhạc đã biểu diễn một giai điệu vui tươi bắt tai mà ai cũng yêu thích.","audio":"vocab-audio/flyers/285.mp3"},{"en":"wild","vi":"hoang dã","art":"1f42f","ipa":"/waɪld/","example":"Lions and tigers are powerful wild creatures of nature.","exampleVi":"Sư tử và hổ là những sinh vật hoang dã mạnh mẽ của tự nhiên.","audio":"vocab-audio/flyers/286.mp3"},{"en":"zoo","vi":"sở thú","art":"1f992","ipa":"/zuː/","example":"The city zoo protects many endangered species of wildlife.","exampleVi":"Sở thú thành phố bảo tồn nhiều loài động vật hoang dã có nguy cơ tuyệt chủng.","audio":"vocab-audio/flyers/287.mp3"}],"art":"1f3aa"},{"id":"6","title":"Dream jobs","words":[{"en":"artist","vi":"họa sĩ","art":"1f469-200d-1f3a8","ipa":"/ˈɑː.tɪst/","example":"The talented artist painted a vivid landscape of the mountains.","exampleVi":"Người họa sĩ tài năng đã vẽ một bức tranh phong cảnh sống động về những ngọn núi.","audio":"vocab-audio/flyers/288.mp3"},{"en":"astronaut","vi":"phi hành gia","art":"1f469-200d-1f680","ipa":"/ˈæs.trə.nɔːt/","example":"An astronaut must train extensively before travelling into space.","exampleVi":"Một phi hành gia phải huấn luyện kỹ lưỡng trước khi bay vào không gian vũ trụ.","audio":"vocab-audio/flyers/289.mp3"},{"en":"bandage","vi":"băng cứu thương","art":"1fa79","ipa":"/ˈbæn.dɪdʒ/","example":"The nurse wrapped a clean white bandage around his sore knee.","exampleVi":"Cô y tá đã quấn một chiếc băng cứu thương màu trắng sạch quanh đầu gối đau của cậu ấy.","audio":"vocab-audio/flyers/290.mp3"},{"en":"begin","vi":"bắt đầu","art":"25b6","ipa":"/bɪˈɡɪn/","example":"The competition will begin as soon as all players are ready.","exampleVi":"Cuộc thi sẽ bắt đầu ngay khi tất cả các người chơi đã sẵn sàng.","audio":"vocab-audio/flyers/291.mp3"},{"en":"businessman","vi":"nam doanh nhân","art":"1f4bc","ipa":"/ˈbɪz.nɪs.mæn/","example":"The successful businessman travels abroad for meetings every month.","exampleVi":"Nam doanh nhân thành đạt đi công tác nước ngoài để họp mỗi tháng.","audio":"vocab-audio/flyers/292.mp3"},{"en":"businesswoman","vi":"nữ doanh nhân","art":"1f469-200d-1f4bc","ipa":"/ˈbɪz.nɪsˌwʊm.ən/","example":"My mother is a businesswoman who manages a modern company.","exampleVi":"Mẹ tôi là một nữ doanh nhân quản lý một công ty hiện đại.","audio":"vocab-audio/flyers/293.mp3"},{"en":"cook","vi":"đầu bếp","art":"1f468-200d-1f373","ipa":"/kʊk/","example":"The head cook prepared delicious dishes for the hotel guests.","exampleVi":"Bếp trưởng đầu bếp đã chuẩn bị những món ăn ngon miệng cho khách của khách sạn.","audio":"vocab-audio/flyers/294.mp3"},{"en":"dentist","vi":"nha sĩ","art":"1fa7b","ipa":"/ˈden.tɪst/","example":"You should visit the dentist twice a year to check your teeth.","exampleVi":"Bạn nên đi khám nha sĩ hai lần một năm để kiểm tra răng.","audio":"vocab-audio/flyers/295.mp3"},{"en":"designer","vi":"nhà thiết kế","art":"1f469-200d-1f3a8","ipa":"/dɪˈzaɪ.nər/","example":"She works as a fashion designer creating stylish clothes.","exampleVi":"Cô ấy làm nghề nhà thiết kế thời trang tạo ra những bộ trang phục phong cách.","audio":"vocab-audio/flyers/296.mp3"},{"en":"doctor","vi":"bác sĩ","art":"1fa7a","ipa":"/ˈdɒk.tər/","example":"The doctor examined the patient and prescribed effective medicine.","exampleVi":"Bác sĩ đã khám cho bệnh nhân và kê đơn thuốc hiệu quả.","audio":"vocab-audio/flyers/297.mp3"},{"en":"each","vi":"mỗi","art":"1f449","ipa":"/iːtʃ/","example":"Each student was given a dictionary at the start of the course.","exampleVi":"Mỗi học sinh được phát một cuốn từ điển vào đầu khóa học.","audio":"vocab-audio/flyers/298.mp3"},{"en":"early","vi":"sớm","art":"1f305","ipa":"/ˈɜː.li/","example":"Farmers wake up early in the morning to look after their animals.","exampleVi":"Những người nông dân thức dậy sớm vào buổi sáng để chăm sóc đàn vật nuôi.","audio":"vocab-audio/flyers/299.mp3"},{"en":"engineer","vi":"kỹ sư","art":"1f477","ipa":"/ˌen.dʒɪˈnɪər/","example":"The software engineer designed a clever program for schools.","exampleVi":"Người kỹ sư phần mềm đã thiết kế một chương trình thông minh cho các trường học.","audio":"vocab-audio/flyers/300.mp3"},{"en":"fast","vi":"nhanh","art":"26a1","ipa":"/fɑːst/","example":"The express train travels remarkably fast between major cities.","exampleVi":"Tàu tốc hành di chuyển cực kỳ nhanh giữa các thành phố lớn.","audio":"vocab-audio/flyers/301.mp3"},{"en":"fire fighter","vi":"lính cứu hỏa","art":"1f468-200d-1f692","ipa":"/ˈfaɪəˌfaɪ.tər/","example":"The courageous fire fighter saved the family from the fire.","exampleVi":"Người lính cứu hỏa dũng cảm đã cứu sống gia đình khỏi đám cháy.","audio":"vocab-audio/flyers/302.mp3"},{"en":"happen","vi":"xảy ra","art":"2753","ipa":"/ˈhæp.ən/","example":"Strange things can happen when you explore ancient castles.","exampleVi":"Những điều kỳ lạ có thể xảy ra khi bạn khám phá những lâu đài cổ.","audio":"vocab-audio/flyers/303.mp3"},{"en":"job","vi":"nghề nghiệp","art":"1f4bc","ipa":"/dʒɒb/","example":"She hopes to find an exciting job as an aerospace engineer.","exampleVi":"Cô ấy hy vọng tìm được một nghề nghiệp hào hứng như kỹ sư hàng không vũ trụ.","audio":"vocab-audio/flyers/304.mp3"},{"en":"journalist","vi":"nhà báo","art":"1f4dd","ipa":"/ˈdʒɜː.nə.lɪst/","example":"The journalist interviewed the famous athlete after the race.","exampleVi":"Nhà báo đã phỏng vấn vận động viên nổi tiếng sau cuộc đua.","audio":"vocab-audio/flyers/305.mp3"},{"en":"lazy","vi":"lười biếng","art":"1f9a5","ipa":"/ˈleɪ.zi/","example":"Don't be lazy, review your English vocabulary every single day.","exampleVi":"Đừng lười biếng, hãy ôn tập từ vựng tiếng Anh của bạn mỗi ngày nhé.","audio":"vocab-audio/flyers/306.mp3"},{"en":"look after","vi":"chăm sóc","art":"1f932","ipa":"/lʊk ˈɑːf.tər/","example":"Could you please look after my pet rabbit while I am away?","exampleVi":"Bạn có thể vui lòng chăm sóc chú thỏ cưng của tôi trong lúc tôi đi vắng không?","audio":"vocab-audio/flyers/307.mp3"},{"en":"manager","vi":"người quản lý","art":"1f468-200d-1f4bc","ipa":"/ˈmæn.ɪ.dʒər/","example":"The hotel manager greeted all the international guests warmly.","exampleVi":"Người quản lý khách sạn đã nồng nhiệt chào đón tất cả các du khách quốc tế.","audio":"vocab-audio/flyers/308.mp3"},{"en":"mechanic","vi":"thợ máy","art":"1f527","ipa":"/məˈkæn.ɪk/","example":"The skilled mechanic repaired the engine in less than two hours.","exampleVi":"Người thợ máy lành nghề đã sửa xong động cơ trong vòng chưa đầy hai giờ.","audio":"vocab-audio/flyers/309.mp3"},{"en":"meeting","vi":"cuộc họp","art":"1f4ca","ipa":"/ˈmiː.tɪŋ/","example":"Teachers held an important meeting to discuss the new timetable.","exampleVi":"Các giáo viên đã tổ chức một cuộc họp quan trọng để thảo luận về thời khóa biểu mới.","audio":"vocab-audio/flyers/310.mp3"},{"en":"nowhere","vi":"không nơi nào","art":"1f6ab","ipa":"/ˈnəʊ.weər/","example":"The missing keys were nowhere to be found in the entire house.","exampleVi":"Những chiếc chìa khóa bị mất không thể tìm thấy ở bất kỳ nơi nào trong cả ngôi nhà.","audio":"vocab-audio/flyers/311.mp3"},{"en":"nurse","vi":"y tá","art":"1f9d1-200d-2695-fe0f","ipa":"/nɜːs/","example":"The kind nurse checked my temperature and gave me advice.","exampleVi":"Cô y tá tốt bụng đã kiểm tra nhiệt độ của tôi và đưa ra lời khuyên.","audio":"vocab-audio/flyers/312.mp3"},{"en":"office","vi":"văn phòng","art":"1f3e2","ipa":"/ˈɒf.ɪs/","example":"My father works in a modern office in the city centre.","exampleVi":"Bố tôi làm việc tại một văn phòng hiện đại ở trung tâm thành phố.","audio":"vocab-audio/flyers/313.mp3"},{"en":"perhaps","vi":"có lẽ","art":"1f914","ipa":"/pəˈhæps/","example":"Perhaps we could visit the natural history museum this weekend.","exampleVi":"Có lẽ chúng ta có thể đến thăm bảo tàng lịch sử tự nhiên vào cuối tuần này.","audio":"vocab-audio/flyers/314.mp3"},{"en":"photographer","vi":"nhiếp ảnh gia","art":"1f4f7","ipa":"/fəˈtɒɡ.rə.fər/","example":"The wildlife photographer took stunning pictures of eagles.","exampleVi":"Nhiếp ảnh gia động vật hoang dã đã chụp những bức ảnh tuyệt đẹp về loài đại bàng.","audio":"vocab-audio/flyers/315.mp3"},{"en":"pilot","vi":"phi công","art":"1f468-200d-2708-fe0f","ipa":"/ˈpaɪ.lət/","example":"The airline pilot announced that the plane was about to land.","exampleVi":"Phi công của hãng hàng không đã thông báo rằng máy bay sắp hạ cánh.","audio":"vocab-audio/flyers/316.mp3"},{"en":"police officer","vi":"cảnh sát","art":"1f46e","ipa":"/pəˈliːs ˌɒf.ɪ.sər/","example":"The police officer helped the lost tourist find the station.","exampleVi":"Viên cảnh sát đã giúp người khách du lịch bị lạc tìm thấy nhà ga.","audio":"vocab-audio/flyers/317.mp3"},{"en":"poor","vi":"nghèo","art":"1f97a","ipa":"/pɔːr/","example":"The poor little dog was shivering outside in the cold rain.","exampleVi":"Chú chó nhỏ tội nghiệp đang run rẩy ngoài trời mưa lạnh.","audio":"vocab-audio/flyers/318.mp3"},{"en":"rich","vi":"giàu","art":"1f911","ipa":"/rɪtʃ/","example":"The king was extraordinarily rich with vaults full of gold.","exampleVi":"Vị vua vô cùng giàu có với những hầm chứa đầy vàng bạc.","audio":"vocab-audio/flyers/319.mp3"},{"en":"singer","vi":"ca sĩ","art":"1f3a4","ipa":"/ˈsɪŋ.ər/","example":"The talented singer performed a beautiful tune on the stage.","exampleVi":"Người ca sĩ tài năng đã thể hiện một giai điệu tuyệt đẹp trên sân khấu.","audio":"vocab-audio/flyers/320.mp3"},{"en":"teacher","vi":"giáo viên","art":"1f469-200d-1f3eb","ipa":"/ˈtiː.tʃər/","example":"Our science teacher encouraged us to do our own experiments.","exampleVi":"Giáo viên khoa học của chúng tôi đã khuyến khích chúng tôi tự làm thí nghiệm.","audio":"vocab-audio/flyers/321.mp3"},{"en":"tennis player","vi":"vận động viên quần vợt","art":"1f3be","ipa":"/ˈten.ɪs ˌpleɪ.ər/","example":"The young tennis player won a trophy in the school tournament.","exampleVi":"Vận động viên quần vợt trẻ đã giành được chiếc cúp trong giải đấu của trường.","audio":"vocab-audio/flyers/322.mp3"},{"en":"waiter","vi":"nhân viên phục vụ nam","art":"1f9d1-200d-1f373","ipa":"/ˈweɪ.tər/","example":"The polite waiter brought our delicious meals to the table.","exampleVi":"Người nhân viên phục vụ nam lịch sự đã mang những món ăn ngon ra bàn cho chúng tôi.","audio":"vocab-audio/flyers/323.mp3"}],"art":"1f469-200d-1f680"},{"id":"7","title":"At the castle","words":[{"en":"appear","vi":"xuất hiện","art":"2728","ipa":"/əˈpɪər/","example":"Rainbows often appear in the sky after a sudden shower.","exampleVi":"Cầu vồng thường xuất hiện trên bầu trời sau một cơn mưa rào bất chợt.","audio":"vocab-audio/flyers/324.mp3"},{"en":"bridge","vi":"cây cầu","art":"1f309","ipa":"/brɪdʒ/","example":"An old wooden bridge connects the castle to the forest.","exampleVi":"Một cây cầu gỗ cũ nối lâu đài với khu rừng.","audio":"vocab-audio/flyers/325.mp3"},{"en":"building","vi":"tòa nhà","art":"1f3e2","ipa":"/ˈbɪl.dɪŋ/","example":"The library is an impressive building with high stone walls.","exampleVi":"Thư viện là một tòa nhà ấn tượng với những bức tường đá cao.","audio":"vocab-audio/flyers/326.mp3"},{"en":"butterfly","vi":"bươm bướm","art":"1f98b","ipa":"/ˈbʌt.ə.flaɪ/","example":"A colourful butterfly landed gently on the fragrant flower.","exampleVi":"Một chú bươm bướm sặc sỡ đậu nhẹ nhàng lên bông hoa ngát hương.","audio":"vocab-audio/flyers/327.mp3"},{"en":"century","vi":"thế kỷ","art":"1f570","ipa":"/ˈsen.tʃər.i/","example":"This royal palace was built during the seventeenth century.","exampleVi":"Cung điện hoàng gia này được xây dựng trong suốt thế kỷ mười bảy.","audio":"vocab-audio/flyers/328.mp3"},{"en":"conversation","vi":"cuộc hội thoại","art":"1f4ac","ipa":"/ˌkɒn.vəˈseɪ.ʃən/","example":"We had an interesting conversation about ancient civilizations.","exampleVi":"Chúng tôi đã có một cuộc hội thoại thú vị về các nền văn minh cổ đại.","audio":"vocab-audio/flyers/329.mp3"},{"en":"costume","vi":"trang phục hóa trang","art":"1f3ad","ipa":"/ˈkɒs.tʃuːm/","example":"She wore a traditional royal costume to the festival.","exampleVi":"Cô ấy đã mặc một bộ trang phục hóa trang hoàng gia truyền thống đến lễ hội.","audio":"vocab-audio/flyers/330.mp3"},{"en":"creature","vi":"sinh vật","art":"1f916","ipa":"/ˈkriː.tʃər/","example":"The ocean is home to many mysterious and colourful creatures.","exampleVi":"Đại dương là ngôi nhà của nhiều sinh vật kỳ bí và rực rỡ sắc màu.","audio":"vocab-audio/flyers/331.mp3"},{"en":"crown","vi":"vương miện","art":"1f451","ipa":"/kraʊn/","example":"The golden crown was decorated with sparkling precious stones.","exampleVi":"Chiếc vương miện bằng vàng được trang trí bằng những viên đá quý lấp lánh.","audio":"vocab-audio/flyers/332.mp3"},{"en":"date","vi":"ngày tháng","art":"1f4c5","ipa":"/deɪt/","example":"What is the date of the upcoming science competition?","exampleVi":"Ngày tháng của cuộc thi khoa học sắp tới là khi nào vậy?","audio":"vocab-audio/flyers/333.mp3"},{"en":"design","vi":"thiết kế","art":"1f3a8","ipa":"/dɪˈzaɪn/","example":"The architect will design an eco-friendly building for the city.","exampleVi":"Kiến trúc sư sẽ thiết kế một tòa nhà thân thiện với môi trường cho thành phố.","audio":"vocab-audio/flyers/334.mp3"},{"en":"east","vi":"hướng đông","art":"27a1","ipa":"/iːst/","example":"The sun rises in the east and sets in the west.","exampleVi":"Mặt trời mọc ở hướng đông và lặn ở hướng tây.","audio":"vocab-audio/flyers/335.mp3"},{"en":"entrance","vi":"lối vào","art":"1f6aa","ipa":"/ˈen.trəns/","example":"Visitors must buy tickets before walking through the entrance.","exampleVi":"Khách tham quan phải mua vé trước khi đi qua lối vào.","audio":"vocab-audio/flyers/336.mp3"},{"en":"exit","vi":"lối ra","art":"1f6be","ipa":"/ˈek.sɪt/","example":"Follow the green signs to reach the emergency exit quickly.","exampleVi":"Hãy đi theo các biển chỉ dẫn màu xanh để đến lối ra thoát hiểm một cách nhanh chóng.","audio":"vocab-audio/flyers/337.mp3"},{"en":"festival","vi":"lễ hội","art":"1f38f","ipa":"/ˈfes.tɪval/","example":"Villagers celebrate the autumn harvest festival every year.","exampleVi":"Dân làng tổ chức lễ hội mừng mùa thu hoạch mỗi năm.","audio":"vocab-audio/flyers/338.mp3"},{"en":"finger","vi":"ngón tay","art":"1f90f","ipa":"/ˈfɪŋ.ɡər/","example":"He pointed his finger toward the high tower of the castle.","exampleVi":"Cậu ấy đã chỉ ngón tay của mình về phía tòa tháp cao của lâu đài.","audio":"vocab-audio/flyers/339.mp3"},{"en":"flag","vi":"lá cờ","art":"1f3f3","ipa":"/flæɡ/","example":"A bright national flag waved proudly in the morning wind.","exampleVi":"Một lá cờ tổ quốc tươi sáng tung bay kiêu hãnh trong gió sớm.","audio":"vocab-audio/flyers/340.mp3"},{"en":"follow","vi":"đi theo","art":"1f463","ipa":"/ˈfɒl.əʊ/","example":"Please follow the tour guide to explore the castle gardens.","exampleVi":"Làm ơn hãy đi theo hướng dẫn viên để khám phá các khu vườn của lâu đài.","audio":"vocab-audio/flyers/341.mp3"},{"en":"gate","vi":"cổng","art":"1f3f0","ipa":"/ɡeɪt/","example":"The heavy iron gate of the fortress was locked tightly.","exampleVi":"Chiếc cổng sắt nặng nề của pháo đài đã được khóa chặt.","audio":"vocab-audio/flyers/342.mp3"},{"en":"glass","vi":"thủy tinh","art":"1f943","ipa":"/ɡlɑːs/","example":"The ancient museum windows were crafted from stained glass.","exampleVi":"Những khung cửa sổ bảo tàng cổ được chế tác từ thủy tinh màu.","audio":"vocab-audio/flyers/343.mp3"},{"en":"gold","vi":"vàng","art":"1f947","ipa":"/ɡəʊld/","example":"The queen wore a heavy ring made of pure gold.","exampleVi":"Nữ hoàng đã đeo một chiếc nhẫn nặng làm bằng vàng nguyên chất.","audio":"vocab-audio/flyers/344.mp3"},{"en":"insect","vi":"côn trùng","art":"1f41b","ipa":"/ˈɪn.sekt/","example":"Beetles and butterflies belong to the large insect family.","exampleVi":"Bọ cánh cứng và bươm bướm thuộc về họ côn trùng rộng lớn.","audio":"vocab-audio/flyers/345.mp3"},{"en":"interested","vi":"quan tâm, hứng thú","art":"1f929","ipa":"/ˈɪn.trəs.tɪd/","example":"Are you interested in learning about astronauts and rockets?","exampleVi":"Bạn có quan tâm hứng thú với việc tìm hiểu về các phi hành gia và tên lửa không?","audio":"vocab-audio/flyers/346.mp3"},{"en":"journey","vi":"hành trình","art":"1f9f3","ipa":"/ˈdʒɜː.ni/","example":"Their journey across the desert took nearly three weeks.","exampleVi":"Hành trình của họ băng qua sa mạc kéo dài gần ba tuần.","audio":"vocab-audio/flyers/347.mp3"},{"en":"king","vi":"nhà vua","art":"1f451","ipa":"/kɪŋ/","example":"The brave king ruled his kingdom wisely for forty years.","exampleVi":"Vị nhà vua dũng cảm đã cai trị vương quốc một cách thông thái suốt bốn mươi năm.","audio":"vocab-audio/flyers/348.mp3"},{"en":"leave","vi":"rời đi","art":"1f3c3","ipa":"/liːv/","example":"We must leave now if we want to catch the evening train.","exampleVi":"Chúng ta phải rời đi ngay bây giờ nếu muốn bắt kịp chuyến tàu tối.","audio":"vocab-audio/flyers/349.mp3"},{"en":"make sure","vi":"đảm bảo","art":"2705","ipa":"/meɪk ʃɔːr/","example":"Make sure you bring your warm sleeping bag for the camp.","exampleVi":"Hãy đảm bảo rằng bạn mang theo túi ngủ ấm áp cho buổi cắm trại.","audio":"vocab-audio/flyers/350.mp3"},{"en":"might","vi":"có thể","art":"1f914","ipa":"/maɪt/","example":"Take an umbrella because it might rain in the afternoon.","exampleVi":"Hãy mang theo một chiếc ô vì trời có thể sẽ mưa vào buổi chiều.","audio":"vocab-audio/flyers/351.mp3"},{"en":"north","vi":"hướng bắc","art":"2b06","ipa":"/nɔːθ/","example":"The compass needle always points toward the frozen north.","exampleVi":"Kim la bàn luôn luôn chỉ về hướng bắc băng giá.","audio":"vocab-audio/flyers/352.mp3"},{"en":"postcard","vi":"bưu thiếp","art":"1f4ee","ipa":"/ˈpəʊst.kɑːd/","example":"I sent a postcard of the medieval castle to my penfriend.","exampleVi":"Tôi đã gửi một tấm bưu thiếp chụp lâu đài thời trung cổ cho bạn qua thư.","audio":"vocab-audio/flyers/353.mp3"},{"en":"queen","vi":"nữ hoàng","art":"1f478","ipa":"/kwiːn/","example":"The queen smiled graciously as she welcomed foreign leaders.","exampleVi":"Nữ hoàng mỉm cười tao nhã khi chào đón các nhà lãnh đạo nước ngoài.","audio":"vocab-audio/flyers/354.mp3"},{"en":"ring","vi":"chiếc nhẫn","art":"1f48d","ipa":"/rɪŋ/","example":"Her antique silver ring was passed down through generations.","exampleVi":"Chiếc nhẫn bạc cổ của bà được truyền lại qua nhiều thế hệ.","audio":"vocab-audio/flyers/355.mp3"},{"en":"send","vi":"gửi","art":"1f4e4","ipa":"/send/","example":"I will send an electronic invitation to everyone today.","exampleVi":"Tôi sẽ gửi một lời mời điện tử đến tất cả mọi người trong hôm nay.","audio":"vocab-audio/flyers/356.mp3"},{"en":"silver","vi":"bạc","art":"1f948","ipa":"/ˈsɪl.vər/","example":"The winner was awarded a shiny silver trophy on stage.","exampleVi":"Người chiến thắng đã được trao một chiếc cúp bạc sáng bóng trên sân khấu.","audio":"vocab-audio/flyers/357.mp3"},{"en":"south","vi":"hướng nam","art":"2b07","ipa":"/saʊθ/","example":"Birds migrate south to escape the cold winter months.","exampleVi":"Những đàn chim bay về hướng nam để tránh những tháng mùa đông giá rét.","audio":"vocab-audio/flyers/358.mp3"},{"en":"steps","vi":"bậc thang","art":"1fa9c","ipa":"/steps/","example":"We climbed two hundred stone steps to reach the castle gate.","exampleVi":"Chúng tôi đã leo hai trăm bậc thang đá để đến được cổng lâu đài.","audio":"vocab-audio/flyers/359.mp3"},{"en":"still","vi":"vẫn","art":"23f3","ipa":"/stɪl/","example":"Even after sixty years, the castle still stands majestically.","exampleVi":"Ngay cả sau sáu mươi năm, tòa lâu đài vẫn đứng sừng sững uy nghiêm.","audio":"vocab-audio/flyers/360.mp3"},{"en":"swan","vi":"thiên nga","art":"1f9a2","ipa":"/swɒn/","example":"A graceful white swan was gliding across the quiet lake.","exampleVi":"Một chú thiên nga trắng duyên dáng đang lướt đi trên mặt hồ yên ả.","audio":"vocab-audio/flyers/361.mp3"},{"en":"swing","vi":"xích đu","art":"1fa81","ipa":"/swɪŋ/","example":"The child played happily on the swing beneath the oak tree.","exampleVi":"Đứa trẻ chơi đùa vui vẻ trên chiếc xích đu dưới bóng cây sồi.","audio":"vocab-audio/flyers/362.mp3"},{"en":"touch","vi":"chạm","art":"1f446","ipa":"/tʌtʃ/","example":"Visitors are strictly asked not to touch the museum exhibits.","exampleVi":"Khách tham quan được yêu cầu nghiêm ngặt không chạm vào hiện vật bảo tàng.","audio":"vocab-audio/flyers/363.mp3"},{"en":"tour","vi":"chuyến tham quan","art":"1f68c","ipa":"/tʊər/","example":"We joined a guided tour to discover the secrets of the fortress.","exampleVi":"Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn để khám phá bí mật pháo đài.","audio":"vocab-audio/flyers/364.mp3"},{"en":"unusual","vi":"khác thường","art":"1fa84","ipa":"/ʌnˈjuː.ʒu.əl/","example":"The explorer discovered an unusual insect with bright blue wings.","exampleVi":"Nhà thám hiểm đã phát hiện một loài côn trùng khác thường với đôi cánh xanh biếc.","audio":"vocab-audio/flyers/365.mp3"},{"en":"view","vi":"quang cảnh","art":"1f3de","ipa":"/vjuː/","example":"From the castle tower, we had a panoramic view of the valley.","exampleVi":"Từ tháp lâu đài, chúng tôi đã có một quang cảnh bao quát toàn thung lũng.","audio":"vocab-audio/flyers/366.mp3"},{"en":"west","vi":"hướng tây","art":"2b05","ipa":"/west/","example":"The explorer travelled west toward the setting golden sun.","exampleVi":"Nhà thám hiểm đi về hướng tây hướng về phía mặt trời lặn vàng rực.","audio":"vocab-audio/flyers/367.mp3"},{"en":"wild","vi":"hoang dã","art":"1f42f","ipa":"/waɪld/","example":"Lions and tigers are powerful wild creatures of nature.","exampleVi":"Sư tử và hổ là những sinh vật hoang dã mạnh mẽ của tự nhiên.","audio":"vocab-audio/flyers/368.mp3"},{"en":"wonderful","vi":"tuyệt vời","art":"1f929","ipa":"/ˈwʌn.də.fəl/","example":"We had a wonderful camping experience under the clear stars.","exampleVi":"Chúng tôi đã có một trải nghiệm cắm trại tuyệt vời dưới bầu trời đầy sao sáng.","audio":"vocab-audio/flyers/369.mp3"}],"art":"1f3f0"},{"id":"8","title":"Sports day!","words":[{"en":"already","vi":"đã rồi","art":"2705","ipa":"/ɔːlˈred.i/","example":"The football match has already started, so let's hurry up.","exampleVi":"Trận đấu bóng đá đã bắt đầu rồi, vì vậy chúng ta hãy nhanh lên.","audio":"vocab-audio/flyers/370.mp3"},{"en":"competition","vi":"cuộc thi","art":"1f3c6","ipa":"/ˌkɒm.pəˈtɪʃ.ən/","example":"Over twenty schools participated in the swimming competition.","exampleVi":"Hơn hai mươi trường đã tham gia vào cuộc thi bơi lội.","audio":"vocab-audio/flyers/371.mp3"},{"en":"end","vi":"kết thúc","art":"1f3c1","ipa":"/end/","example":"The thrilling race came to an end with a photo finish.","exampleVi":"Cuộc đua kịch tính đã đi đến hồi kết thúc với khoảng cách sít sao.","audio":"vocab-audio/flyers/372.mp3"},{"en":"explain","vi":"giải thích","art":"1f5e3","ipa":"/ɪkˈspleɪn/","example":"Can you explain the rules of badminton to the beginners?","exampleVi":"Bạn có thể giải thích luật chơi cầu lông cho những người mới bắt đầu không?","audio":"vocab-audio/flyers/373.mp3"},{"en":"fall over","vi":"vấp ngã","art":"1f6b6","ipa":"/fɔːl ˈəʊ.vər/","example":"Be careful on the ice rink or you will fall over.","exampleVi":"Hãy cẩn thận trên sân trượt băng kẻo bạn sẽ vấp ngã đấy.","audio":"vocab-audio/flyers/374.mp3"},{"en":"goal","vi":"bàn thắng","art":"1f945","ipa":"/ɡəʊl/","example":"He scored the winning goal in the final minute of the match.","exampleVi":"Cậu ấy đã ghi bàn thắng quyết định ở phút cuối cùng của trận đấu.","audio":"vocab-audio/flyers/375.mp3"},{"en":"golf","vi":"môn gôn","art":"26f3","ipa":"/ɡɒlf/","example":"My grandfather plays golf with his friends every Saturday.","exampleVi":"Ông tôi chơi môn gôn với bạn bè vào mỗi thứ Bảy.","audio":"vocab-audio/flyers/376.mp3"},{"en":"just","vi":"vừa mới","art":"23f1","ipa":"/dʒʌst/","example":"The school sports day has just begun on the main field.","exampleVi":"Ngày hội thể thao của trường vừa mới bắt đầu trên sân chính.","audio":"vocab-audio/flyers/377.mp3"},{"en":"knee","vi":"đầu gối","art":"1f9b5","ipa":"/niː/","example":"He bandaged his injured knee after the hard football tackle.","exampleVi":"Cậu ấy đã băng bó chiếc đầu gối bị thương sau pha tranh bóng quyết liệt.","audio":"vocab-audio/flyers/378.mp3"},{"en":"match","vi":"trận đấu","art":"26bd","ipa":"/mætʃ/","example":"Our team won the championship match by three goals to two.","exampleVi":"Đội của chúng tôi đã chiến thắng trận đấu chung kết với tỉ số ba-hai.","audio":"vocab-audio/flyers/379.mp3"},{"en":"prize","vi":"giải thưởng","art":"1f947","ipa":"/praɪz/","example":"The fastest runner received a golden prize and a certificate.","exampleVi":"Người chạy nhanh nhất đã nhận được một giải thưởng bằng vàng và giấy chứng nhận.","audio":"vocab-audio/flyers/380.mp3"},{"en":"race","vi":"cuộc đua","art":"1f3c3","ipa":"/reɪs/","example":"Ten runners took part in the one-hundred-metre race.","exampleVi":"Mười vận động viên đã tham gia cuộc đua chạy một trăm mét.","audio":"vocab-audio/flyers/381.mp3"},{"en":"score","vi":"điểm số","art":"1f3af","ipa":"/skɔːr/","example":"What is the final score between the two football teams?","exampleVi":"Điểm số chung cuộc giữa hai đội bóng đá là bao nhiêu vậy?","audio":"vocab-audio/flyers/382.mp3"},{"en":"snack","vi":"bữa ăn nhẹ","art":"1f37f","ipa":"/snæk/","example":"Have a healthy fruit snack before training for the race.","exampleVi":"Hãy ăn một bữa ăn nhẹ bằng trái cây lành mạnh trước khi tập luyện cho cuộc đua.","audio":"vocab-audio/flyers/383.mp3"},{"en":"sore","vi":"đau nhức","art":"1fa79","ipa":"/sɔːr/","example":"My leg muscles were sore after running five kilometres.","exampleVi":"Các cơ chân của tôi bị đau nhức sau khi chạy năm ki-lô-mét.","audio":"vocab-audio/flyers/384.mp3"},{"en":"team","vi":"đội","art":"1f465","ipa":"/tiːm/","example":"Our school volleyball team has practised hard all term.","exampleVi":"Đội bóng chuyền trường chúng tôi đã tập luyện chăm chỉ suốt học kỳ.","audio":"vocab-audio/flyers/385.mp3"},{"en":"volleyball","vi":"bóng chuyền","art":"1f3d0","ipa":"/ˈvɒl.i.bɔːl/","example":"We enjoyed playing volleyball on the sandy beach yesterday.","exampleVi":"Hôm qua chúng tôi đã rất thích chơi bóng chuyền trên bãi cát.","audio":"vocab-audio/flyers/386.mp3"},{"en":"winner","vi":"người chiến thắng","art":"1f3c5","ipa":"/ˈwɪn.ər/","example":"The winner of the bicycle race crossed the finish line first.","exampleVi":"Người chiến thắng cuộc đua xe đạp đã cán đích đầu tiên.","audio":"vocab-audio/flyers/387.mp3"},{"en":"yet","vi":"chưa (trong câu phủ định)","art":"23f3","ipa":"/jet/","example":"Has the coach announced the starting lineup for the team yet?","exampleVi":"Huấn luyện viên đã công bố đội hình xuất phát cho đội bóng chưa?","audio":"vocab-audio/flyers/388.mp3"}],"art":"1f3c5"},{"id":"R2","title":"Revision 2","words":[{"en":"engine","vi":"động cơ","art":"2699","ipa":"/ˈen.dʒɪn/","example":"The mechanic listened carefully to the humming sound of the engine.","exampleVi":"Người thợ máy lắng nghe kỹ tiếng nổ êm của động cơ.","audio":"vocab-audio/flyers/389.mp3"},{"en":"invent","vi":"phát minh","art":"1f4a1","ipa":"/ɪnˈvent/","example":"Clever scientists continually invent new tools to explore space.","exampleVi":"Những nhà khoa học thông minh liên tục phát minh ra các công cụ mới để khám phá vũ trụ.","audio":"vocab-audio/flyers/390.mp3"},{"en":"racing car","vi":"xe đua","art":"1f3ce","ipa":"/ˈreɪ.sɪŋ ˌkɑːr/","example":"The streamlined racing car sped around the track at high speed.","exampleVi":"Chiếc xe đua dáng khí động học lao vun vút quanh đường đua với tốc độ cao.","audio":"vocab-audio/flyers/391.mp3"},{"en":"repair","vi":"sửa chữa","art":"1f527","ipa":"/rɪˈpeər/","example":"It took two experienced mechanics to repair the damaged engine.","exampleVi":"Cần hai thợ máy giàu kinh nghiệm để sửa chữa động cơ bị hư hỏng.","audio":"vocab-audio/flyers/392.mp3"},{"en":"suddenly","vi":"đột nhiên","art":"26a1","ipa":"/ˈsʌd.ən.li/","example":"Suddenly, fireworks lit up the midnight sky with bright colors.","exampleVi":"Đột nhiên, pháo hoa thắp sáng bầu trời đêm với những màu sắc rực rỡ.","audio":"vocab-audio/flyers/393.mp3"},{"en":"win","vi":"chiến thắng","art":"1f3c6","ipa":"/wɪn/","example":"If we train diligently together, our team can win the trophy.","exampleVi":"Nếu chúng ta cùng nhau tập luyện chăm chỉ, đội mình có thể chiến thắng chiếc cúp.","audio":"vocab-audio/flyers/394.mp3"}],"art":"1f3c6"},{"id":"9","title":"Our camping adventure","words":[{"en":"alone","vi":"một mình","art":"1f9cd","ipa":"/əˈləʊn/","example":"You must never hike alone into the dense mountain forest.","exampleVi":"Bạn không bao giờ được đi bộ đường dài một mình vào khu rừng rậm trên núi.","audio":"vocab-audio/flyers/395.mp3"},{"en":"belt","vi":"thắt lưng","art":"1faa2","ipa":"/belt/","example":"Fasten your leather belt securely before climbing the rocks.","exampleVi":"Hãy thắt chặt chiếc thắt lưng da của bạn trước khi leo lên các tảng đá.","audio":"vocab-audio/flyers/396.mp3"},{"en":"biscuits","vi":"những chiếc bánh quy","art":"1f36a","ipa":"/ˈbɪs.kɪts/","example":"We packed some sweet oatmeal biscuits for our camping trip.","exampleVi":"Chúng tôi đã đóng gói những chiếc bánh quy yến mạch ngọt ngào cho chuyến cắm trại.","audio":"vocab-audio/flyers/397.mp3"},{"en":"burn","vi":"cháy","art":"1f525","ipa":"/bɜːn/","example":"Dry wood will burn brightly and keep the campsite warm.","exampleVi":"Gỗ khô sẽ cháy bừng sáng và giữ ấm cho khu cắm trại.","audio":"vocab-audio/flyers/398.mp3"},{"en":"camp","vi":"cắm trại","art":"1f3d5","ipa":"/kæmp/","example":"We set up our green tents at the quiet lakeside camp.","exampleVi":"Chúng tôi đã dựng những chiếc lều xanh tại khu cắm trại yên tĩnh bên hồ.","audio":"vocab-audio/flyers/399.mp3"},{"en":"cave","vi":"hang động","art":"1f3de","ipa":"/keɪv/","example":"Explorers discovered prehistoric drawings inside the dark cave.","exampleVi":"Các nhà thám hiểm đã phát hiện ra những hình vẽ thời tiền sử bên trong hang động tối tăm.","audio":"vocab-audio/flyers/400.mp3"},{"en":"dark","vi":"tối","art":"1f311","ipa":"/dɑːk/","example":"It was completely dark inside the cave without our torches.","exampleVi":"Bên trong hang động tối đen hoàn toàn nếu không có đèn pin của chúng tôi.","audio":"vocab-audio/flyers/401.mp3"},{"en":"decide","vi":"quyết định","art":"2705","ipa":"/dɪˈsaɪd/","example":"We must decide whether to climb the hill or explore the valley.","exampleVi":"Chúng ta phải quyết định xem nên leo lên đồi hay đi khám phá thung lũng.","audio":"vocab-audio/flyers/402.mp3"},{"en":"deep","vi":"sâu","art":"1f30a","ipa":"/diːp/","example":"The river was too deep and fast to cross safely on foot.","exampleVi":"Dòng sông quá sâu và chảy xiết để có thể lội bộ qua một cách an toàn.","audio":"vocab-audio/flyers/403.mp3"},{"en":"Earth","vi":"Trái Đất","art":"1f30d","ipa":"/ɜːθ/","example":"The Earth is the only known planet that supports plant and animal life.","exampleVi":"Trái Đất là hành tinh duy nhất được biết đến có sự sống của động thực vật.","audio":"vocab-audio/flyers/404.mp3"},{"en":"elbow","vi":"khuỷu tay","art":"1f9be","ipa":"/ˈel.bəʊ/","example":"He wore a protective pad on his elbow while skateboarding.","exampleVi":"Cậu ấy đã đeo một miếng đệm bảo vệ ở khuỷu tay khi trượt ván.","audio":"vocab-audio/flyers/405.mp3"},{"en":"explore","vi":"khám phá","art":"1f9ed","ipa":"/ɪkˈsplɔːr/","example":"Astronauts and scientists continue to explore distant parts of space.","exampleVi":"Các phi hành gia và nhà khoa học tiếp tục khám phá những vùng xa xôi của không gian vũ trụ.","audio":"vocab-audio/flyers/406.mp3"},{"en":"fire","vi":"lửa","art":"1f525","ipa":"/faɪər/","example":"We sat around the campfire singing cheerful tunes under the stars.","exampleVi":"Chúng tôi ngồi quanh đống lửa trại hát những bài ca vui tươi dưới bầu trời đầy sao.","audio":"vocab-audio/flyers/407.mp3"},{"en":"fur","vi":"lông thú","art":"1f43b","ipa":"/fɜːr/","example":"Polar bears have thick white fur to keep them warm in freezing cold.","exampleVi":"Gấu bắc cực có bộ lông thú dày màu trắng để giữ ấm trong giá rét.","audio":"vocab-audio/flyers/408.mp3"},{"en":"furry","vi":"có lông","art":"1f436","ipa":"/ˈfɜː.ri/","example":"The children fell in love with the cute, furry puppy at the shelter.","exampleVi":"Những đứa trẻ đã mê tít chú cún con có lông mềm mại dễ thương ở trạm cứu hộ.","audio":"vocab-audio/flyers/409.mp3"},{"en":"heavy","vi":"nặng","art":"1f4aa","ipa":"/ˈhev.i/","example":"The camping rucksack was too heavy for the young boy to carry.","exampleVi":"Chiếc ba lô cắm trại quá nặng đối với cậu bé để có thể mang vác.","audio":"vocab-audio/flyers/410.mp3"},{"en":"hill","vi":"đồi","art":"26f0","ipa":"/hɪl/","example":"We pitched our tents at the foot of a green hill.","exampleVi":"Chúng tôi đã dựng lều ở dưới chân một ngọn đồi xanh.","audio":"vocab-audio/flyers/411.mp3"},{"en":"horrible","vi":"kinh khủng","art":"1f635","ipa":"/ˈhɒr.ə.bl/","example":"The thunderstorm last night caused horrible damage to the campsite.","exampleVi":"Cơn bão sấm sét đêm qua đã gây ra thiệt hại kinh khủng cho khu cắm trại.","audio":"vocab-audio/flyers/412.mp3"},{"en":"kilometre","vi":"ki-lô-mét","art":"1f6e3","ipa":"/ˈkɪl.əˌmiː.tər/","example":"The hiking trail runs for fifteen kilometres through the forest.","exampleVi":"Đường mòn đi bộ kéo dài mười lăm ki-lô-mét xuyên qua khu rừng.","audio":"vocab-audio/flyers/413.mp3"},{"en":"large","vi":"to lớn","art":"1f418","ipa":"/lɑːdʒ/","example":"A large flock of birds flew across the evening sky.","exampleVi":"Một đàn chim to lớn bay lượn ngang qua bầu trời buổi chiều.","audio":"vocab-audio/flyers/414.mp3"},{"en":"magazine","vi":"tạp chí","art":"1f4f0","ipa":"/ˌmæɡ.əˈziːn/","example":"She bought a wildlife magazine to read on the train journey.","exampleVi":"Cô ấy đã mua một cuốn tạp chí động vật hoang dã để đọc trong chuyến đi tàu.","audio":"vocab-audio/flyers/415.mp3"},{"en":"missing","vi":"mất tích","art":"1f50d","ipa":"/ˈmɪs.ɪŋ/","example":"Park rangers searched the mountain trail for the missing camper.","exampleVi":"Những nhân viên kiểm lâm đã tìm kiếm trên đường mòn trên núi người cắm trại bị mất tích.","audio":"vocab-audio/flyers/416.mp3"},{"en":"nest","vi":"tổ chim","art":"1faba","ipa":"/nest/","example":"The eagle built its large nest high up on the mountain cliff.","exampleVi":"Con đại bàng đã làm chiếc tổ chim lớn trên vách núi cao.","audio":"vocab-audio/flyers/417.mp3"},{"en":"newspaper","vi":"báo","art":"1f4f4","ipa":"/ˈnjuːzˌpeɪ.pər/","example":"Grandpa reads the morning newspaper while having breakfast.","exampleVi":"Ông đọc tờ báo buổi sáng trong khi ăn điểm tâm.","audio":"vocab-audio/flyers/418.mp3"},{"en":"path","vi":"đường mòn","art":"1f6e4","ipa":"/pɑːθ/","example":"Follow this narrow stone path to reach the waterfall.","exampleVi":"Hãy đi theo con đường mòn bằng đá hẹp này để đến được thác nước.","audio":"vocab-audio/flyers/419.mp3"},{"en":"pocket","vi":"túi áo, quần","art":"1f456","ipa":"/ˈpɒk.ɪt/","example":"Keep your compass in your front pocket so you don't lose it.","exampleVi":"Hãy để la bàn trong túi áo trước để không làm mất nó nhé.","audio":"vocab-audio/flyers/420.mp3"},{"en":"rock","vi":"tảng đá","art":"1faa8","ipa":"/rɒk/","example":"Be careful because the wet rock near the waterfall is slippery.","exampleVi":"Hãy cẩn thận vì tảng đá ướt gần thác nước rất trơn trượt.","audio":"vocab-audio/flyers/421.mp3"},{"en":"soft","vi":"mềm","art":"1f9f8","ipa":"/sɒft/","example":"The grass in the mountain valley was delightfully green and soft.","exampleVi":"Bãi cỏ ở thung lũng miền núi xanh mát và mềm mại dễ chịu.","audio":"vocab-audio/flyers/422.mp3"},{"en":"stars","vi":"những ngôi sao","art":"2728","ipa":"/stɑːz/","example":"Millions of bright stars illuminated the clear midnight sky.","exampleVi":"Hàng triệu những ngôi sao sáng đã thắp sáng bầu trời đêm thanh tĩnh.","audio":"vocab-audio/flyers/423.mp3"},{"en":"stone","vi":"viên đá","art":"1faa8","ipa":"/stəʊn/","example":"Ancient people carved mysterious symbols into the large stone.","exampleVi":"Người cổ đại đã khắc những ký hiệu bí ẩn lên viên đá lớn.","audio":"vocab-audio/flyers/424.mp3"},{"en":"strange","vi":"kỳ lạ","art":"1f914","ipa":"/streɪndʒ/","example":"We heard a strange animal sound coming from the dark cave.","exampleVi":"Chúng tôi nghe thấy một âm thanh động vật kỳ lạ phát ra từ hang động tối.","audio":"vocab-audio/flyers/425.mp3"},{"en":"tent","vi":"lều","art":"26fa","ipa":"/tent/","example":"Make sure the tent is secured against strong winds.","exampleVi":"Hãy đảm bảo rằng chiếc lều đã được chằng buộc chắc chắn trước gió mạnh.","audio":"vocab-audio/flyers/426.mp3"},{"en":"together","vi":"cùng nhau","art":"1f91d","ipa":"/təˈɡeð.ər/","example":"We worked together as a team to set up the campsite.","exampleVi":"Chúng tôi đã cùng nhau làm việc như một đội để dựng khu cắm trại.","audio":"vocab-audio/flyers/427.mp3"},{"en":"torch","vi":"đèn pin","art":"1f526","ipa":"/tɔːtʃ/","example":"Always carry a powerful torch when walking after sunset.","exampleVi":"Hãy luôn mang theo một chiếc đèn pin sáng khi đi bộ sau hoàng hôn.","audio":"vocab-audio/flyers/428.mp3"},{"en":"tyre","vi":"lốp xe","art":"1f6de","ipa":"/taɪər/","example":"The mountain bike had a puncture in its rear tyre.","exampleVi":"Chiếc xe đạp leo núi bị thủng một lỗ ở lốp xe phía sau.","audio":"vocab-audio/flyers/429.mp3"},{"en":"umbrella","vi":"ô, dù","art":"2602","ipa":"/ʌmˈbrel.ə/","example":"A sturdy umbrella will protect you from heavy mountain rain.","exampleVi":"Một chiếc ô chắc chắn sẽ che chở cho bạn khỏi những cơn mưa lớn trên núi.","audio":"vocab-audio/flyers/430.mp3"},{"en":"whisper","vi":"thì thầm","art":"1f92b","ipa":"/ˈwɪs.pər/","example":"Speak in a whisper so you don't frighten the sleeping animals.","exampleVi":"Hãy nói thì thầm để bạn không làm những con vật đang ngủ sợ hãi.","audio":"vocab-audio/flyers/431.mp3"},{"en":"whistle","vi":"huýt sáo","art":"1f3c1","ipa":"/ˈwɪs.l/","example":"The scout leader blew his whistle to call everyone to the camp.","exampleVi":"Người đội trưởng hướng đạo đã huýt sáo để gọi mọi người tập hợp ở trại.","audio":"vocab-audio/flyers/432.mp3"},{"en":"wing","vi":"cánh","art":"1f985","ipa":"/wɪŋ/","example":"The wounded eagle had hurt its left wing and couldn't fly.","exampleVi":"Con đại bàng bị thương ở chiếc cánh trái và không thể bay được.","audio":"vocab-audio/flyers/433.mp3"},{"en":"wood","vi":"gỗ","art":"1fab5","ipa":"/wʊd/","example":"We collected dry wood from the ground to light a warm fire.","exampleVi":"Chúng tôi đã nhặt những cành gỗ khô trên mặt đất để nhóm lên ngọn lửa ấm.","audio":"vocab-audio/flyers/434.mp3"}],"art":"1f3d5"},{"id":"10","title":"A good year!","words":[{"en":"autumn","vi":"mùa thu","art":"1f342","ipa":"/ˈɔː.təm/","example":"In autumn, the forest trees change colour from green to gold.","exampleVi":"Vào mùa thu, cây cối trong rừng chuyển màu từ xanh lá sang vàng óng.","audio":"vocab-audio/flyers/435.mp3"},{"en":"collect","vi":"sưu tầm","art":"1f4e6","ipa":"/kəˈlekt/","example":"Children love to collect colourful autumn leaves in the park.","exampleVi":"Trẻ em thích sưu tầm những chiếc lá mùa thu sặc sỡ trong công viên.","audio":"vocab-audio/flyers/436.mp3"},{"en":"enter","vi":"đi vào, tham gia","art":"27a1","ipa":"/ˈen.tər/","example":"Students who want to enter the sports competition must sign up.","exampleVi":"Những học sinh muốn tham gia cuộc thi thể thao phải đăng ký trước.","audio":"vocab-audio/flyers/437.mp3"},{"en":"grow","vi":"phát triển","art":"1f331","ipa":"/ɡrəʊ/","example":"Vegetables grow exceptionally well in the rich black soil.","exampleVi":"Các loại rau củ phát triển rất tốt trên mảnh đất màu mỡ.","audio":"vocab-audio/flyers/438.mp3"},{"en":"leaf","vi":"chiếc lá","art":"1f343","ipa":"/liːf/","example":"A bright red maple leaf fell quietly onto her shoulder.","exampleVi":"Một chiếc lá phong màu đỏ tươi rơi nhẹ nhàng lên vai cô ấy.","audio":"vocab-audio/flyers/439.mp3"},{"en":"lie","vi":"nằm","art":"1f6cc","ipa":"/laɪ/","example":"It is relaxing to lie on the warm beach under the sunshine.","exampleVi":"Thật thư thái khi nằm trên bãi biển ấm áp dưới ánh nắng mặt trời.","audio":"vocab-audio/flyers/440.mp3"},{"en":"pull","vi":"kéo","art":"1f9f2","ipa":"/pʊl/","example":"The strong husky dogs pull the heavy sledge through the snow.","exampleVi":"Những chú chó husky khỏe mạnh kéo chiếc xe trượt tuyết nặng qua lớp tuyết.","audio":"vocab-audio/flyers/441.mp3"},{"en":"push","vi":"đẩy","art":"1f44b","ipa":"/pʊʃ/","example":"We had to push the car when it got stuck in the thick mud.","exampleVi":"Chúng tôi đã phải đẩy chiếc xe ô tô khi nó bị mắc kẹt trong bùn lầy.","audio":"vocab-audio/flyers/442.mp3"},{"en":"sledge","vi":"xe trượt tuyết","art":"1f6f7","ipa":"/sledʒ/","example":"The children rode their wooden sledge down the snowy slope.","exampleVi":"Những đứa trẻ đã trượt chiếc xe trượt tuyết bằng gỗ xuống con dốc đầy tuyết.","audio":"vocab-audio/flyers/443.mp3"},{"en":"snowball","vi":"quả cầu tuyết","art":"2744","ipa":"/ˈsnəʊ.bɔːl/","example":"They laughed happily while having a friendly snowball fight.","exampleVi":"Họ cười đùa vui vẻ trong khi chơi ném quả cầu tuyết cùng nhau.","audio":"vocab-audio/flyers/444.mp3"},{"en":"snowboard","vi":"ván trượt tuyết","art":"1f3c2","ipa":"/ˈsnəʊ.bɔːd/","example":"He bought a professional snowboard for his winter holiday.","exampleVi":"Cậu ấy đã mua một chiếc ván trượt tuyết chuyên nghiệp cho kỳ nghỉ đông.","audio":"vocab-audio/flyers/445.mp3"},{"en":"snowman","vi":"người tuyết","art":"26c4","ipa":"/ˈsnəʊ.mæn/","example":"We built a jolly snowman with a carrot nose in the garden.","exampleVi":"Chúng tôi đã đắp một người tuyết vui vẻ với chiếc mũi bằng củ cà rốt trong vườn.","audio":"vocab-audio/flyers/446.mp3"},{"en":"spring","vi":"mùa xuân","art":"1f338","ipa":"/sprɪŋ/","example":"In spring, birds sing joyfully and flowers bloom everywhere.","exampleVi":"Vào mùa xuân, chim hót líu lo và hoa nở rộ khắp nơi.","audio":"vocab-audio/flyers/447.mp3"},{"en":"summer","vi":"mùa hè","art":"2600","ipa":"/ˈsʌm.ər/","example":"We usually spend our long summer holidays near the ocean.","exampleVi":"Chúng tôi thường trải qua những kỳ nghỉ mùa hè dài ngày ở gần đại dương.","audio":"vocab-audio/flyers/448.mp3"},{"en":"trip","vi":"chuyến đi","art":"1f697","ipa":"/trɪp/","example":"Our school organized an educational trip to the space centre.","exampleVi":"Trường chúng tôi đã tổ chức một chuyến đi học tập đến trung tâm vũ trụ.","audio":"vocab-audio/flyers/449.mp3"},{"en":"winter","vi":"mùa đông","art":"26c4","ipa":"/ˈwɪn.tər/","example":"Winter in the north is often freezing with heavy snowfall.","exampleVi":"Mùa đông ở miền bắc thường giá buốt với tuyết rơi dày đặc.","audio":"vocab-audio/flyers/450.mp3"},{"en":"wish","vi":"điều ước","art":"1f91e","ipa":"/wɪʃ/","example":"Close your eyes and make a special wish before blowing out candles.","exampleVi":"Hãy nhắm mắt lại và ước một điều ước đặc biệt trước khi thổi nến.","audio":"vocab-audio/flyers/451.mp3"},{"en":"x-ray","vi":"ảnh chụp X-quang","art":"1fa7b","ipa":"/ˈeks.reɪ/","example":"The doctor examined the x-ray to see if any bones were broken.","exampleVi":"Bác sĩ đã kiểm tra ảnh chụp X-quang để xem có chiếc xương nào bị gãy không.","audio":"vocab-audio/flyers/452.mp3"}],"art":"1f342"},{"id":"11","title":"Our summer holidays","words":[{"en":"camel","vi":"lạc đà","art":"1f42a","ipa":"/ˈkæm.əl/","example":"A camel can travel for days in the desert without water.","exampleVi":"Một con lạc đà có thể di chuyển nhiều ngày trên sa mạc mà không cần nước.","audio":"vocab-audio/flyers/453.mp3"},{"en":"desert","vi":"sa mạc","art":"1f3dc","ipa":"/ˈdez.ət/","example":"The Sahara is the largest hot desert in the entire world.","exampleVi":"Sahara là sa mạc nóng lớn nhất trên toàn thế giới.","audio":"vocab-audio/flyers/454.mp3"},{"en":"environment","vi":"môi trường","art":"1f331","ipa":"/ɪnˈvaɪ.rən.mənt/","example":"We must plant more trees to protect our natural environment.","exampleVi":"Chúng ta phải trồng nhiều cây hơn để bảo vệ môi trường tự nhiên của chúng ta.","audio":"vocab-audio/flyers/455.mp3"},{"en":"ever","vi":"đã từng","art":"2728","ipa":"/ˈev.ər/","example":"Have you ever ridden a camel across a sandy desert?","exampleVi":"Bạn đã từng cưỡi một con lạc đà băng qua sa mạc cát chưa?","audio":"vocab-audio/flyers/456.mp3"},{"en":"foggy","vi":"có sương mù","art":"1f32b","ipa":"/ˈfɒɡ.i/","example":"It was so foggy that drivers could barely see the road.","exampleVi":"Trời có sương mù dày đặc đến nỗi các tài xế khó có thể nhìn thấy đường.","audio":"vocab-audio/flyers/457.mp3"},{"en":"gloves","vi":"găng tay","art":"1f9e4","ipa":"/ɡlʌvz/","example":"Wear thick woollen gloves to keep your fingers warm.","exampleVi":"Hãy đeo đôi găng tay len dày để giữ ấm cho các ngón tay của bạn.","audio":"vocab-audio/flyers/458.mp3"},{"en":"lift","vi":"thang máy","art":"1f6d7","ipa":"/lɪft/","example":"The modern hotel has a glass lift with a view of the city.","exampleVi":"Khách sạn hiện đại có một chiếc thang máy bằng kính nhìn ra toàn thành phố.","audio":"vocab-audio/flyers/459.mp3"},{"en":"London","vi":"Luân Đôn","art":"1f3db","ipa":"/ˈlʌn.dən/","example":"London is a historic capital city famous for its museums and palaces.","exampleVi":"Luân Đôn là một thủ đô lịch sử nổi tiếng với các bảo tàng và cung điện.","audio":"vocab-audio/flyers/460.mp3"},{"en":"meet","vi":"gặp","art":"1f91d","ipa":"/miːt/","example":"I will meet my classmates at the entrance of the museum.","exampleVi":"Tôi sẽ gặp các bạn cùng lớp tại lối vào của bảo tàng.","audio":"vocab-audio/flyers/461.mp3"},{"en":"octopus","vi":"bạch tuộc","art":"1f419","ipa":"/ˈɒk.tə.pəs/","example":"An octopus has eight arms and is an exceptionally clever sea creature.","exampleVi":"Bạch tuộc có tám xúc tu và là một sinh vật biển đặc biệt thông minh.","audio":"vocab-audio/flyers/462.mp3"},{"en":"pop music","vi":"nhạc pop","art":"1f3a4","ipa":"/ˈpɒp ˌmjuː.zɪk/","example":"Young people around the world enjoy listening to modern pop music.","exampleVi":"Giới trẻ khắp thế giới rất thích nghe nhạc pop hiện đại.","audio":"vocab-audio/flyers/463.mp3"},{"en":"raining","vi":"đang mưa","art":"1f327","ipa":"/ˈreɪ.nɪŋ/","example":"It was raining cats and dogs when we left the theatre.","exampleVi":"Trời đang mưa như trút nước khi chúng tôi rời khỏi nhà hát.","audio":"vocab-audio/flyers/464.mp3"},{"en":"rock music","vi":"nhạc rock","art":"1f3b8","ipa":"/ˈrɒk ˌmjuː.zɪk/","example":"The electric guitar sounded amazing in the live rock music concert.","exampleVi":"Cây đàn ghi-ta điện vang lên tuyệt vời trong buổi biểu diễn nhạc rock trực tiếp.","audio":"vocab-audio/flyers/465.mp3"},{"en":"should","vi":"nên","art":"2754","ipa":"/ʃʊd/","example":"You should drink plenty of fresh water during hot summer days.","exampleVi":"Bạn nên uống nhiều nước lọc trong những ngày hè nắng nóng.","audio":"vocab-audio/flyers/466.mp3"},{"en":"snowing","vi":"đang có tuyết","art":"2744","ipa":"/ˈsnəʊ.ɪŋ/","example":"It was snowing heavily on the mountains all through the night.","exampleVi":"Tuyết đang rơi dày đặc trên những ngọn núi suốt cả đêm.","audio":"vocab-audio/flyers/467.mp3"},{"en":"spotted","vi":"có đốm","art":"1f406","ipa":"/ˈspɒt.ɪd/","example":"The leopard has a spotted coat that helps it camouflage in the grass.","exampleVi":"Báo gấm có bộ lông có đốm giúp nó ngụy trang trong đám cỏ.","audio":"vocab-audio/flyers/468.mp3"},{"en":"storm","vi":"cơn bão","art":"26c8","ipa":"/stɔːm/","example":"The fierce storm damaged several old trees in the village.","exampleVi":"Cơn bão dữ dội đã làm gãy đổ vài cây cổ thụ trong ngôi làng.","audio":"vocab-audio/flyers/469.mp3"},{"en":"striped","vi":"có sọc","art":"1f993","ipa":"/straɪpt/","example":"Zebras have distinctive striped black-and-white coats.","exampleVi":"Ngựa vằn có bộ lông có sọc đen trắng rất đặc trưng.","audio":"vocab-audio/flyers/470.mp3"},{"en":"suitcase","vi":"va li","art":"1f9f3","ipa":"/ˈsuːt.keɪs/","example":"She packed all her summer holiday clothes into a red suitcase.","exampleVi":"Cô ấy đã xếp tất cả quần áo nghỉ hè vào một chiếc va li màu đỏ.","audio":"vocab-audio/flyers/471.mp3"},{"en":"sunglasses","vi":"kính râm","art":"1f576","ipa":"/ˈsʌnˌɡlɑːs.ɪz/","example":"Always wear sunglasses to protect your eyes from strong sunlight.","exampleVi":"Hãy luôn đeo kính râm để bảo vệ đôi mắt khỏi ánh nắng mặt trời gay gắt.","audio":"vocab-audio/flyers/472.mp3"},{"en":"sunny","vi":"có nắng","art":"2600","ipa":"/ˈsʌn.i/","example":"The Mediterranean climate is warm and sunny for most of the year.","exampleVi":"Khí hậu Địa Trung Hải ấm áp và có nắng trong hầu hết cả năm.","audio":"vocab-audio/flyers/473.mp3"},{"en":"toe","vi":"ngón chân","art":"1f9b6","ipa":"/təʊ/","example":"He accidentally bumped his big toe against the heavy table leg.","exampleVi":"Cậu ấy đã vô tình va ngón chân cái vào chiếc chân bàn nặng.","audio":"vocab-audio/flyers/474.mp3"},{"en":"trainers","vi":"giày thể thao","art":"1f45f","ipa":"/ˈtreɪ.nəz/","example":"I bought a pair of supportive trainers for the running race.","exampleVi":"Tôi đã mua một đôi giày thể thao êm ái cho cuộc chạy đua.","audio":"vocab-audio/flyers/475.mp3"}],"art":"1f42a"},{"id":"12","title":"Past and future","words":[{"en":"calendar","vi":"lịch","art":"1f4c6","ipa":"/ˈkæl.ən.dər/","example":"Mark the date of the school sports festival on your calendar.","exampleVi":"Hãy đánh dấu ngày diễn ra lễ hội thể thao trường lên cuốn lịch của bạn.","audio":"vocab-audio/flyers/476.mp3"},{"en":"eagle","vi":"đại bàng","art":"1f985","ipa":"/ˈiː.ɡl/","example":"A majestic eagle soared high above the deep mountain valley.","exampleVi":"Một con đại bàng uy nghi bay lượn trên cao phía trên thung lũng núi sâu.","audio":"vocab-audio/flyers/477.mp3"},{"en":"enough","vi":"đủ","art":"1f44d","ipa":"/ɪˈnʌf/","example":"We have enough food and fresh water for the whole weekend trip.","exampleVi":"Chúng ta có đủ thức ăn và nước uống cho cả chuyến đi cuối tuần.","audio":"vocab-audio/flyers/478.mp3"},{"en":"future","vi":"tương lai","art":"1f680","ipa":"/ˈfjuː.tʃər/","example":"Technological advances will change the way we live in the future.","exampleVi":"Những tiến bộ công nghệ sẽ thay đổi cách chúng ta sống trong tương lai.","audio":"vocab-audio/flyers/479.mp3"},{"en":"guess","vi":"đoán","art":"1f914","ipa":"/ɡes/","example":"Can you guess how many planets orbit our solar system?","exampleVi":"Bạn có thể đoán có bao nhiêu hành tinh quay quanh hệ mặt trời của chúng ta không?","audio":"vocab-audio/flyers/480.mp3"},{"en":"hope","vi":"hy vọng","art":"1f91e","ipa":"/həʊp/","example":"I hope humanity will discover signs of life on other planets.","exampleVi":"Tôi hy vọng loài người sẽ phát hiện ra dấu vết sự sống trên các hành tinh khác.","audio":"vocab-audio/flyers/481.mp3"},{"en":"land","vi":"đất, hạ cánh","art":"1f30d","ipa":"/lænd/","example":"The lunar module will land gently on the surface of the moon.","exampleVi":"Mô-đun mặt trăng sẽ hạ cánh êm đềm lên bề mặt của mặt trăng.","audio":"vocab-audio/flyers/482.mp3"},{"en":"past","vi":"quá khứ","art":"1f995","ipa":"/pɑːst/","example":"Historians study ancient ruins to understand life in the past.","exampleVi":"Các nhà sử học nghiên cứu những tàn tích cổ đại để hiểu về cuộc sống trong quá khứ.","audio":"vocab-audio/flyers/483.mp3"},{"en":"planet","vi":"hành tinh","art":"1fa90","ipa":"/ˈplæn.ɪt/","example":"Mars is known as the red planet due to its iron-rich soil.","exampleVi":"Sao Hỏa được gọi là hành tinh đỏ do đất đai giàu chất sắt.","audio":"vocab-audio/flyers/484.mp3"},{"en":"pond","vi":"ao","art":"1f41f","ipa":"/pɒnd/","example":"Water lilies and colourful fish thrive in the school garden pond.","exampleVi":"Hoa súng và những đàn cá sặc sỡ phát triển tươi tốt trong ao vườn trường.","audio":"vocab-audio/flyers/485.mp3"},{"en":"racing bike","vi":"xe đạp đua","art":"1f6b4","ipa":"/ˈreɪ.sɪŋ ˌbaɪk/","example":"He rode his lightweight racing bike to victory in the tournament.","exampleVi":"Cậu ấy đã lái chiếc xe đạp đua siêu nhẹ đến chiến thắng trong giải đấu.","audio":"vocab-audio/flyers/486.mp3"},{"en":"ready","vi":"sẵn sàng","art":"2705","ipa":"/ˈred.i/","example":"The astronauts were completely ready for the historic rocket launch.","exampleVi":"Các phi hành gia đã hoàn toàn sẵn sàng cho vụ phóng tên lửa lịch sử.","audio":"vocab-audio/flyers/487.mp3"},{"en":"rocket","vi":"tên lửa","art":"1f680","ipa":"/ˈrɒk.ɪt/","example":"A powerful space rocket launched the satellite into orbit.","exampleVi":"Một tên lửa vũ trụ mạnh mẽ đã phóng vệ tinh vào quỹ đạo.","audio":"vocab-audio/flyers/488.mp3"},{"en":"ski","vi":"trượt tuyết","art":"26f7","ipa":"/skiː/","example":"We learned how to ski down the gentle snowy slopes in winter.","exampleVi":"Chúng tôi đã học cách trượt tuyết xuống những con dốc phủ tuyết thoai thoải vào mùa đông.","audio":"vocab-audio/flyers/489.mp3"},{"en":"space","vi":"không gian vũ trụ","art":"1f30c","ipa":"/speɪs/","example":"Telescopes allow astronomers to gaze deep into outer space.","exampleVi":"Kính thiên văn cho phép các nhà thiên văn học nhìn sâu vào không gian vũ trụ bao la.","audio":"vocab-audio/flyers/490.mp3"},{"en":"spaceship","vi":"tàu vũ trụ","art":"1f6f8","ipa":"/ˈspeɪs.ʃɪp/","example":"The spaceship was designed to travel safely through the cosmos.","exampleVi":"Con tàu vũ trụ được thiết kế để du hành an toàn qua vũ trụ.","audio":"vocab-audio/flyers/491.mp3"},{"en":"steam","vi":"hơi nước","art":"2668","ipa":"/stiːm/","example":"Steam rose steadily from the engine of the antique railway train.","exampleVi":"Hơi nước bốc lên đều đặn từ động cơ của đoàn tàu hỏa cổ.","audio":"vocab-audio/flyers/492.mp3"},{"en":"worried","vi":"lo lắng","art":"1f61f","ipa":"/ˈwʌr.id/","example":"Don't be worried about the test, you have studied thoroughly.","exampleVi":"Đừng quá lo lắng về bài kiểm tra, bạn đã ôn tập rất kỹ lưỡng rồi.","audio":"vocab-audio/flyers/493.mp3"}],"art":"1f680"},{"id":"R3","title":"Revision 3","words":[{"en":"ice","vi":"băng, nước đá","art":"1f9ca","ipa":"/aɪs/","example":"Polar explorers encountered thick shelves of ice in Antarctica.","exampleVi":"Những nhà thám hiểm vùng cực đã bắt gặp những thềm băng dày ở Nam Cực.","audio":"vocab-audio/flyers/494.mp3"}],"art":"1f3c6"}];
